programs.sol:
"""A sparse approximation to the component's document-opening responses.

Escaped newlines, type/declaration fragments, numbers and indentation tend
positive; code comments and capitalized person-only dictionary entries tend
negative. These rules apply only while the document repeats its first token.
The much smaller, heterogeneous responses elsewhere are left at zero.
"""
from functools import lru_cache
import wordnet

READS = ()
TYPE_DECLARATIONS = {'class', 'struct', 'enum', 'type', 'namespace'}
SCALAR_TYPES = {'int', 'char', 'float', 'double', 'bool', 'long', 'short'}
FUNCTION_DECLARATIONS = {'def', 'function'}
PREPROCESSOR = {
    '#include', '#define', '#ifdef', '#ifndef', '#if', '#elif', '#else',
    '#endif', '#undef', '#error', '#line', '#pragma',
}


@lru_cache(maxsize=4096)
def opening_value(token):
    if token == r'\n':
        return 1.596
    if token == r'\t':
        return 0.867
    if token in {'str', 'void'}:
        return 1.67
    if token in TYPE_DECLARATIONS:
        return 1.20
    if token in SCALAR_TYPES:
        return 0.50
    if token in FUNCTION_DECLARATIONS:
        return 0.65
    if token in PREPROCESSOR:
        return 0.65
    if token.startswith('#!'):
        return 0.49
    if token.startswith(('//', '/*')):
        return -0.50
    if token.isascii() and token.isdigit():
        return 0.25
    if token and not token.strip('^'):
        return -min(1.56, 0.39 * len(token))
    if token and not token.strip(' '):
        if len(token) == 1:
            return 0.014
        return 0.59 if len(token) % 2 else 0.13
    if token and not token.strip('\t'):
        return -0.27 if len(token) == 1 else -0.45
    word = token.strip()
    if word.isascii() and word.istitle() and word.isalpha():
        if wordnet.categories(word) == {'noun.person'}:
            return -0.31
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first, opening = token, True
    else:
        _, first, opening = carry
        opening = opening and token == first
    value = opening_value(token) if opening else 0.0
    return (doc, first, opening), value

"""A small approximation to a software-name suffix signal.

Capitalized role/type words appended to names are positive, especially database
access and architectural roles. Containers and field names have weaker gains.
Tests, file extensions, and double-underscore separators in workspace clone
names have their own rules. Document starts are negative; an initial Title:
label has a positive colon. State resets at each document boundary.

These rules leave most individual-word and longer-context variation unexplained.
"""
import re

READS = ()

PERSISTENCE = set('repository repo dao'.split())
ARCHITECTURE = set('service model controller component entity reducer'.split())
CONSTRUCTION = set('factory builder binding adapter wrapper impl interface'.split())
MANAGEMENT = set('handler manager provider helper converter formatter util processor '
                 'context module resource delegate presenter selector holder '
                 'gateway'.split())
CONTAINERS = set('list set map array collection tuple dict dictionary vector queue '
                 'stack tree table buffer pool store'.split())
VIEWS = set('view form page activity fragment tile panel widget screen '
            'dialog card block'.split())
PROTOCOL = set('request response command event message packet client server '
               'connection listener callback result action'.split())
FIELDS = set('id name key value index count size length path file item node data info '
             'config option settings parameter attribute property type schema'.split())
TESTS = set('test tests spec specs testcase suite'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    if start:
        prev, recent, pos = '', '', 0
    else:
        prev, recent, pos = carry[1], carry[2], carry[3] + 1
    value = 0.002
    if start:
        value = -0.5 if s[:1].isupper() else -0.3
        if s.startswith('_'):
            value = -1.0
        elif s.startswith('<|'):
            value = 0.0
    else:
        body = s.strip().lstrip('_./-')
        low = body.lower()
        if low in TESTS:
            value = 0.1
        joined = bool(prev[-1:].isalnum()) and not s[:1].isspace()
        if joined and body[:1].isupper() and s[:1].isalpha():
            if low in PERSISTENCE:
                value = 3.2
            elif low in ARCHITECTURE:
                value = 1.7
            elif low in CONSTRUCTION:
                value = 0.8
            elif low in MANAGEMENT or low in VIEWS:
                value = 0.6
            elif low in CONTAINERS or low in PROTOCOL:
                value = 0.35
            elif low in FIELDS:
                value = 0.18
            elif low in TESTS:
                value = 0.55
            else:
                value = 0.04
        if s.startswith('_') and body.isalpha():
            value = 0.5 if low in TESTS else 0.08
        if s.startswith('.'):
            if low in {'ts', 'tsx'}:
                value = 0.55
            elif low in {'h', 'hpp', 'java'}:
                value = 0.4
            elif low in {'jsp', 'xhtml', 'jsx', 'vm'}:
                value = 1.5
            elif low in {'py', 'go'}:
                value = -0.2
            elif low in {'md', 'rst'}:
                value = -0.3
            elif low in {'png', 'jpg', 'jpeg', 'gif', 'svg'}:
                value = -0.5
            elif low in TESTS:
                value = 0.45
        if s == '__':
            clone_name = re.search(r'/workspace/[^/\s\"\'<>]*$', recent)
            value = 0.95 if clone_name else 0.02
        if pos == 1 and s == ':' and prev == 'Title':
            value = 4.05
    return (doc, s, (recent+s)[-160:], pos), float(value)

"""Approximate a multilingual reflexive-form response with spelling and grammar.

Slavic reflexive endings get negative values, generally larger when the suffix
occupies a small token. Common non-reflexive lookalikes are suppressed. English
uses a dictionary heuristic: verb objects are negative, emphatic noun/subject
uses positive, and prepositional objects weaker. Local word frequencies guess
the language of ambiguous Latin-script forms. Hiragana 'さ' separately gets a
positive value. Other forms get zero; context resets at document boundaries.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()
REFLEXIVES = {
    'myself', 'yourself', 'himself', 'herself', 'itself',
    'ourselves', 'yourselves', 'themselves', 'oneself',
}
SUBJECTS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
DETERMINERS = {
    'the', 'a', 'an', 'this', 'that', 'these', 'those', 'my', 'your',
    'his', 'her', 'its', 'our', 'their', 'both', 'each', 'which',
}
PREPOSITIONS = {
    'to', 'for', 'of', 'with', 'at', 'in', 'on', 'from', 'about',
    'against', 'between', 'before', 'after', 'within', 'upon', 'by',
    'without', 'unto', 'among', 'over', 'except',
}
# Non-reflexive nouns and function words sharing the spelling of the suffix.
NONREFLEXIVE = {
    'здесь', 'весь', 'небось', 'авось', 'ось', 'лось', 'рысь', 'гусь',
    'карась', 'русь', 'беларусь', 'смесь', 'запись', 'подпись', 'надпись',
    'опись', 'перепись', 'роспись', 'рукопись', 'живопись', 'летопись',
}
CYRILLIC_WORD = re.compile(r'[А-Яа-яЁёІіЇїЄє]+$')


def language(before):
    words = re.findall(r'[^\W\d_]+', before.lower())[-20:]
    languages = ('en', 'de', 'fr', 'es', 'pt', 'it', 'ro',
                 'cs', 'sk', 'pl', 'sh', 'sl')
    return max(languages, key=lambda lang:
               sum(zipf_frequency(w, lang) for w in words))


def predict(token, before, text=None):
    s = token.strip().lower()
    if s == 'さ':
        return 3.8
    if s in REFLEXIVES:
        clause = re.split(r'[.,;:!?\n]', before)[-1]
        words = re.findall(r"[A-Za-z0-9]+(?:'[a-z]+)?", clause)
        previous = words[-1] if words else ''
        p = previous.lower()
        if p in PREPOSITIONS:
            return 0.6 if s == 'itself' else -0.9
        if p in {'am', 'is', 'are', 'was', 'were'}:
            return 2.7
        pos = wordnet.parts_of_speech(p)
        determined = ('noun' in pos and any(w.lower() in DETERMINERS
                                          for w in words[-3:-1]))
        proper_name = (previous.istitle() and not
                       re.search(r'(?:^|[.!?:\n,-])\s*\w+$', before))
        nominal = (p in SUBJECTS or p.isdigit() or determined or proper_name
                   or 'verb' not in pos)
        if nominal:
            return 3.2 if s == 'itself' else 1.9
        return -3.0

    if s == 'się':
        return -7.3
    if s == 'sich':
        return -1.7
    latin_suffix = re.search(r'(?:[aei]rse|[aei]rsi|[áé]ndose)$', s)
    if s in {'se', 'si', 'sa', 'sie', '-se'} or latin_suffix:
        lang = language(before)
        attached = not token[:1].isspace() and before[-1:].isalpha()
        if s == 'sie':
            return -6.0 if lang == 'pl' else 0.0
        if s == '-se':
            return -5.6 if lang == 'pt' else 0.0
        if latin_suffix:
            if lang in {'es', 'pt'} and s.endswith('se'):
                return -4.5
            return -3.0 if lang == 'it' and s.endswith('si') else 0.0
        if lang in {'cs', 'sk', 'sh', 'sl'}:
            return -3.5 if s in {'se', 'sa'} else -1.0
        if lang == 'ro':
            return -1.9 if s == 'se' else 0.15
        if lang in {'es', 'pt'} and s == 'se':
            if attached:
                return -4.9 if before[-1:].lower() != 's' else 0.0
            return -0.7
        if lang == 'it':
            return -1.8 if s == 'si' else 0.0
        return -0.5 if lang == 'fr' and s == 'se' else 0.0

    match = CYRILLIC_WORD.search(before + token if text is None else text)
    if not match:
        return 0.0
    word = match[0].lower()
    if word == 'се':
        return -4.7
    if word in NONREFLEXIVE or word.endswith(
            ('запись', 'подпись', 'надпись', 'нося', 'брось')):
        return 0.0
    if not word.endswith(('ся', 'сь')):
        return 0.0
    # Number and month stems can temporarily end in the same letters.
    if word.endswith(('деся', 'тыся', 'меся', 'вось')):
        return -1.0
    if word in {'вся', 'уся'}:
        return -1.0
    letters = CYRILLIC_WORD.search(token)
    n = len(letters[0]) if letters else 1
    if word.endswith('сь') and len(word) > 2 and word[-3] not in 'аеёиоуыэюяіїє':
        return -2.5  # Ukrainian adjective fragments, e.g. україн-сь-кий.
    if token[:1].isspace() or len(word) <= n:
        return -2.8 if word.endswith(('ются', 'ятся')) else -3.8
    if n <= 2:
        value = -12.5 if n == 1 else -11.2
        if len(word) <= 4:
            value *= 0.55
        if word.endswith(('ихся', 'ыхся')):
            value *= 0.6
        return value
    if n == 3 and word.endswith('тесь'):
        return -12.2
    # Infinitive, past/imperative, and other finite verb endings.
    if word.endswith('ться'):
        return -9.9 * 0.86 ** max(0, n - 5)
    if word.endswith(('лся', 'лась', 'лось', 'лись', 'сь')):
        return -9.7 * 0.88 ** max(0, n - 5)
    return -8.5 * 0.87 ** max(0, n - 5)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    new = prefix.token_bytes[-1]
    joined = old + new
    value = predict(new.decode('utf-8', errors='replace'),
                    old.decode('utf-8', errors='replace'),
                    joined.decode('utf-8', errors='replace'))
    return (doc, joined[-400:]), float(value)

programs.haiku:
"""Layer-1 MLP output feature 2504 (down_proj): a "chatty, first-person speech" detector.

What it does: the component is switched on in informal, conversational, opinionated
English, mostly on the words that carry the speaker's stance or hedging. The cues
below are English words and punctuation only:
  - hedges and intensifiers: "I think", "a bit", "a little", "a couple (of)", "sort (of)",
    "pretty", "really", "just", "kinda", "seems", "maybe";
  - vague nouns: "something", "someone", "stuff", "thing";
  - evaluative words: "excited", "great", "nice", "good", "thanks", "damn";
  - the speaker's own "I" and its contractions ('m, 've, 'll, 're);
  - exclamations and ellipses: "!", "...", "…";
  - the word right after a spoken filler ("Hmm,", "Well,", "Oh, I", "But I", "Ah!");
  - subject pronouns that open a clause ("it", "that", "this", "you", "we", "but").
It is stronger when the surrounding text has been chatty: a decaying running average
(about 10 tokens) of those cues carries over, and resets at each new document.
It stays near zero in code, lists, formal prose and most content words.

Main idea: predicted activation = sum of the weights of the features that hold at a
position. The weights were fit by least squares on 1024 training rows.
"""

READS = ()

DECAY = 0.9  # per token; the chattiness average forgets over about 10 tokens

HEDGE_AND_EVAL = {
    "think", "really", "pretty", "just", "bit", "little", "couple", "very", "kinda",
    "sort", "seems", "seem", "excited", "great", "good", "nice", "stuff", "thing", "things",
    "something", "someone", "know", "hope", "actually", "quite", "believe", "guess", "feel",
    "lot", "thanks", "thank", "please", "maybe", "probably", "basically", "honestly",
    "totally",
}
EVAL_WORDS = {
    "excited", "unfortunate", "great", "stupid", "damn", "nice", "good", "awesome", "cool",
    "bad", "sad", "happy", "wonderful", "beautiful", "interesting", "fun", "amazing", "funny",
    "wrong", "weird", "crazy", "strange", "fine", "sure", "lovely", "terrible", "annoying",
    "question", "problem", "job", "work", "idea", "thing", "moment", "stuff",
}
FILLERS = {
    "Hmm", "Hm", "Wait", "Ah", "Ahh", "Oh", "Well", "Wow", "yeah", "Yeah", "Yes", "Okay",
    "OK", "So", "But", "Haha", "lol", "Um", "Uh", "Hey", "Aha", "Right",
}
FIRST_PERSON = {"I", "'m", "'ve", "'ll", "'re", "'d"}
CLAUSE_PRONOUNS = {
    "it", "that", "this", "you", "we", "but", "It", "That", "This", "You", "We", "But",
}
EXCLAIM = {"!", "！", "…", "...", "?", "？"}
AFTER_FILLER = {",", ".", "!", "I", "it", "that", "...", "…"}
AFTER_HEDGE = {
    "couple", "sort", "lot", "bit", "little", "going", "think", "seems", "really", "Hmm",
    "Wait", "know", "hope", "Maybe", "maybe", "pretty", "Just", "just", "'m", "kind", "kinda",
}

# Fitted weights, in the order of `features` below.
WEIGHTS = [0.51, 0.45, 0.25, 0.49, 0.11, 0.10, 0.25, 1.18, 0.0]


def norm(s):
    """A token as a word: spaces stripped, curly apostrophes made straight."""
    return s.strip().replace("’", "'")


def is_cue(tok):
    """Whether a token is one of the chatty cues that feed the running average."""
    return tok in HEDGE_AND_EVAL or tok in FIRST_PERSON or tok in EXCLAIM or tok in FILLERS


def features(tok, prev, chatty):
    """The features of one position: the token, the token before it, and the chattiness
    carried over from earlier tokens."""
    return [
        tok in HEDGE_AND_EVAL,
        tok in FIRST_PERSON,
        tok in EXCLAIM,
        prev in FILLERS and tok in AFTER_FILLER,
        tok in CLAUSE_PRONOUNS,
        tok in EVAL_WORDS,
        prev in AFTER_HEDGE,
        chatty,
        1.0,
    ]


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    tok = norm(tokens[-1])
    prev = norm(tokens[-2]) if len(prefix) > 1 else ""
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    chatty = 0.0 if (carry is None or new_doc) else carry
    value = sum(w * float(x) for w, x in zip(WEIGHTS, features(tok, prev, chatty)))
    return DECAY * chatty + (1 - DECAY) * is_cue(tok), value

programs.sol:
"""Local English predicate endings and constructions that introduce more material.

Existence/occurrence, reciprocals, and fixed endings such as 'take place' and
'make sense' are negative. Extraction/insertion particles, causative complements
('make available'), and citation/addition phrases are positive. Unrecognized
text is zero. WordNet supplies verb inflections; only 100 characters of local,
document-specific history are retained. This is not a general syntactic parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
EVENTS = {'exist', 'coexist', 'occur', 'happen', 'arise', 'emerge', 'persist'}
# Verbs selecting a directional particle, rather than a location preposition.
DIRECTIONAL = {
    'out': {'take', 'pull', 'let', 'factor', 'lend', 'hand', 'give', 'bring', 'put', 'send'},
    'in': {'add', 'bring', 'fill', 'factor', 'plug', 'substitute'},
    'together': {'bring', 'put', 'pull', 'gather', 'connect', 'join', 'add'},
    'down': {'bring', 'cut', 'take', 'write', 'put', 'set'},
    'back': {'give', 'pay', 'pull', 'bring', 'plug', 'put'},
    'away': {'take', 'strip', 'keep', 'give'},
    'forward': {'bring', 'put', 'carry'},
    'off': {'take', 'throw', 'turn', 'strip', 'set'},
    'up': {'bring', 'hold', 'pick', 'push', 'chop'},
}
VERBS = EVENTS | set().union(*DIRECTIONAL.values()) | {
    'leave', 'make', 'pay', 'hold', 'apply', 'work', 'check', 'read', 'look',
    'compute', 'recompute', 'see', 'go', 'come', 'follow', 'use', 'keep',
}
MATH = re.compile(
    r'\b(?:equations?|inequalit\w*|conditions?|assumptions?|results?|'
    r'identit\w*|relations?|rules?|propositions?|theorems?|formulas?|statements?)\b'
)


@lru_cache(maxsize=20000)
def verb(word):
    return next((w for w in wordnet.base_forms(word, 'verb') if w in VERBS), word)


def response(word, previous, before, history):
    root = verb(word)
    if root in EVENTS:
        if root in {'exist', 'coexist'}:
            if re.search(
                r'\bthere(?:\s+(?:must|should|may|might|can|could|will))?\s*$',
                history,
            ):
                return 0.7
            return -0.3 if word == 'existing' else -2.8
        if root == 'occur':
            return -3.5
        return -2.2 if root in {'happen', 'arise'} else -1.6
    if word == 'other' and previous == 'each':
        return -2.5
    if word == 'another' and previous == 'one':
        return -1.8
    if before == 'take' and word in {'place', 'part'}:
        return -6.1 if word == 'place' else -1.8
    if word == 'sense' and before == 'make':
        return -3.2
    if word == 'respect' and previous == 'with':
        return -2.6
    if word == 'on' and before == 'go':
        return -2.3 if previous == 'going' else -0.5
    if root == 'hold' and word in {'hold', 'holds'}:
        if MATH.search(history):
            return -3.5
        if previous in {'not', "doesn't", 'still', 'always'}:
            return -2.5
        return -0.6 if word == 'holds' else 0.0
    if root == 'apply' and word in {'apply', 'applies'}:
        if word == 'applies' or previous in {'that', 'which', 'not', 'shall', 'rules', 'standards'}:
            return -1.8
    if word == 'true' and previous in {
        'is', 'are', 'was', 'were', 'be', 'been', 'always', 'still',
        'hold', 'holds', "it's", "that's",
    }:
        return -1.9
    if root == 'work':
        if previous in {'this', 'it', 'that', 'not', 'is', 'are', 'was', 'were'}:
            return -0.5
        return 0.0
    if word == 'example' and re.search(r'\bsee\s+for\s*$', history):
        return 2.5
    if word == 'g' and re.search(r'\bsee,?\s+e\.$', history):
        return 2.8
    if word == 'also':
        if before == 'see':
            return 3.2
        if re.search(r'\bthere\s+(?:is|are|was|were)\s*$', history):
            return 1.8
        return 0.55 if previous in {'has', 'had', 'have', 'me'} else 0.04
    if word == 'again':
        if before in {'check', 'read', 'look', 'compute', 'recompute', 'see'}:
            if previous == 'checked':
                return 0.0
            return 1.9
        return 1.1 if previous == 'once' else 0.0
    if word == 'behind' and before == 'leave':
        return 6.0
    if word == 'aside' and before in {'leave', 'set'}:
        return 3.3
    if word == 'home' and before in {'take', 'bring'}:
        return 5.5
    if word in {'visible', 'possible', 'available', 'necessary'} and before == 'make':
        return 3.2
    if word == 'accountable' and before == 'hold':
        return 3.2
    if word in {'only', 'just', 'both'} and (
        before in {'use', 'keep'} or previous in {'with', 'using', 'not'}
    ):
        return 1.6 if before in {'use', 'keep'} else 0.8
    if before in DIRECTIONAL.get(word, ()):
        if word == 'out' and before == 'take':
            return 3.3
        return {
            'up': 0.6, 'off': 0.9, 'down': 1.3, 'together': 2.2,
            'in': 1.4, 'out': 2.5,
        }.get(word, 1.8)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1].lower().replace('’', "'")
    text = history + token
    match = None
    if token and token[-1].isascii() and token[-1].isalpha():
        match = re.search(r'[a-z]+\Z', text)
    value = 0.0
    if match:
        word = match.group()
        preceding = text[:match.start()]
        words = re.findall(r"[a-z]+(?:'[a-z]+)?", preceding)
        previous = words[-1] if words else ''
        # An underscore or dot marks an identifier/member name, not prose.
        if not preceding.endswith(('_', '.')) or word == 'g':
            value = response(word, previous, verb(previous), preceding)
    return (doc, text[-100:]), value

programs.haiku:
"""Layer-1 MLP down-projection component 2506: a negative 'existence / occurrence
collocation' detector with a weak positive for adverb particles.

It is strongly negative on the word that completes a fixed phrase or a verb of
occurring or existing:
  - "place" in "takes place" / "took place"          (about -6)
  - "other" in "each other"                          (about -2.5)
  - "respect" in "with respect"                      (about -2.7)
  - "sense" in "make sense" / "makes sense"          (about -3.5)
  - verbs of occurrence and existence: occur, happen, exist, hold, apply (-0.5 to -3.7)
  - "true" after is / be / are / not                 (about -1.8)
It is weakly positive (about +0.3) on particles that finish phrasal verbs or
adverbs: out, off, away, together, only, also, again, back, down, forward.
Everything else predicts 0. Only the newest token and the one before it are read.
"""

READS = ()

VERB_VALUE = {
    "occur": -3.5, "occurs": -3.5, "occurred": -3.0, "occurring": -2.9,
    "happen": -2.4, "happens": -2.5, "happened": -1.8, "happening": -2.2,
    "exist": -2.2, "exists": -1.9, "existed": -2.8,
    "hold": -1.4, "holds": -2.0, "apply": -0.6, "applies": -1.7,
    "comes": -0.8, "follows": -0.5, "remain": -0.5, "remains": -0.4,
    "appear": -0.4, "appears": -0.5,
}
PARTICLE_VALUE = {
    "out": 0.45, "together": 0.35, "off": 0.33, "away": 0.3, "only": 0.3,
    "forward": 0.24, "also": 0.19, "again": 0.19, "back": 0.2, "down": 0.18,
}
