"""Approximate an onset pulse that persists through identical initial tokens.

Onset gains distinguish digits, markers, punctuation, scripts, grammatical
classes and physical-scale adjectives. They summarize training responses,
not an exact lexical lookup. After the onset, space-prefixed 'en'/'En' and
bare 'En' receive 0.1, raised to 1.1 when a French function word occurred
within the last 24 tokens. Everything else is silent until a new document.
"""
import regex
import wordnet

READS = ()

ARTICLES = set('a an the'.split())
PERSONAL = set('i me you he him she her it we us they them'.split())
POSSESSIVE = set('my your his its our their mine yours ours theirs'.split())
PREPOSITIONS = set(
    'of in on at to from for by with as about into over under through '
    'between without before after'.split()
)
AUXILIARIES = set(
    'is are was were be been being am has have had do does did can could '
    'will would should shall may might must'.split()
)
CONJUNCTIONS = set(
    'and or but nor so yet if because although while when unless'.split()
)
DETERMINERS = set(
    'this that these those some any each every no all both other another such'.split()
)
# Adjectives describing physical scales: extent, age and temperature.
PHYSICAL_SCALES = set(
    'big small large little great huge tiny wide narrow long short high low '
    'tall deep shallow broad vast new old young fresh recent ancient modern '
    'hot cold warm cool'.split()
)
FRENCH_CLUES = set(
    'les des du une et dans avec est qui aux cette ces pas nous vous '
    'sont leurs mais ont'.split()
)

DIGIT_GAINS = (14.63, 0.17, 4.39, 1.94, 2.76, 3.86, 2.79, 2.19, 3.38, -0.60)


def onset_gain(s):
    w = s.strip()
    lower = w.lower()
    spaced = s.startswith(' ')
    if s == '<|im_start|>':
        return 5.34
    if s == '<|im_end|>':
        return 6.46
    if s == '<|endoftext|>':
        return 4.0
    if s == 'import':  # A source file opening with an import directive.
        return 11.63
    if len(w) == 1 and w in '0123456789':
        return DIGIT_GAINS[int(w)]
    if not w:
        return 4.09 if s == '\t' else -0.63
    if not any(c.isalnum() for c in w):
        if w == '··':  # A middle-dot leader, including repeated leaders.
            return 5.36
        if w[0] in '.,;:!?)]}':
            return -0.5
        if w[0] in '([{':
            return 0.8
        return 1.1
    if not regex.search(r'\p{Script=Latin}', w):
        if regex.search(r'\p{Script=Arabic}', w):
            return 9.5
        if regex.search(r'\p{Script=Cyrillic}', w):
            return 2.75
        return 3.5
    if lower in ARTICLES:
        return 3.82 if spaced else 2.54
    if lower in PERSONAL:
        return -0.64
    if lower in POSSESSIVE:
        return 5.2 if spaced else 7.35
    if lower in PREPOSITIONS:
        return 1.43 if spaced else -0.15
    if lower in AUXILIARIES:
        return -0.58 if spaced else 1.63
    if lower in CONJUNCTIONS:
        return 0.16 if spaced else -1.5
    if lower in DETERMINERS:
        return 1.73 if spaced else 3.77
    if any(base in PHYSICAL_SCALES for base in wordnet.base_forms(lower)):
        return 11.0 if w.istitle() else 8.5
    pos = wordnet.parts_of_speech(lower)
    if 'adjective' in pos:
        return 4.5 if w.istitle() else 3.65
    if 'noun' in pos:
        if w.isupper():
            return 2.5
        return 1.2 if w.istitle() else 1.7
    if 'verb' in pos:
        return 2.1
    if 'adverb' in pos:
        return 0.0
    return 2.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, onset_gain(text), 0)
    doc, initial, uniform, gain, french_recent = carry
    uniform = uniform and token == initial
    # Remember whether a French function word occurred in the last 24 tokens.
    french_recent = (24 if text.strip().lower() in FRENCH_CLUES
                     else max(0, french_recent - 1))
    value = gain if uniform else 0.0
    if not uniform and text in {' en', ' En', 'En'}:
        value = 1.1 if french_recent else 0.1
    return (doc, initial, uniform, gain, french_recent), value

"""Approximate the component's strong response to default/empty initial values.

Recognize literal zero, nulls, booleans, empty containers/strings and empty
calls. Assignments, returns, tests and colons receive different levels.
