# These are levels for semantic literal classes, not a token-id lookup.
LEVELS = {
    'None': (.2, 8.2, 3.9, 2.7, .9, 1.3),
    'null': (.8, 7.0, 4.2, 3.8, 1.1, .9),
    'nil': (.3, 3.5, 1.7, 1.0, .02, .5),
    'undefined': (.3, 3.5, 1.4, 1.7, .3, .8),
    'false': (.25, 4.7, 3.0, 2.2, .6, .5),
    'true': (.16, 2.2, 1.5, .55, .15, .25),
    'list': (.15, 7.3, 2.4, 1.8, 1.8, .8),
    'dict': (.35, 6.3, .4, 1.8, 1.1, 1.5),
    'string': (.3, 5.0, 1.5, 3.0, 1.8, .7),
}
WORD = re.compile(r'[=(.]*?(None|null|NULL|NONE|none|nil|nullptr|undefined|'
                  r'false|False|FALSE|true|True|TRUE)[),;:]*$')
CODE = re.compile(r'\b(?:def|class|import|public|private|var|let|const|void|self)\b|'
                  r'\b(?:int|double|float)\s+[\w*]|'
                  r'\b(?:for|while|if)\s*\(|\bfunction(?:\s+\w+)?\s*\(')
COLLECTION = re.compile(r'\b(?:ArrayList|HashMap|HashSet|List|Map|Set|'
                        r'Dictionary|Vector|Vec)\s*$')
BUILTIN_COLLECTION = re.compile(r'(?<![.\w])(?:list|dict|set|tuple)\s*$')
ACCUMULATOR = re.compile(r'(?:^|_)(?:sum|total|count|counter)(?:_|$)')


def describe(token, tail):
    """Return a human-named category, for calibration or prediction."""
    s = token.strip()
    if s == '0':
        kind, offset = 'zero', 0
    elif '[]' in s and not s.startswith(('"', "'")):
        kind, offset = 'list', s.index('[]')
    elif '{}' in s and not s.startswith(('"', "'")):
        kind, offset = 'dict', s.index('{}')
    elif '()' in s:
        if BUILTIN_COLLECTION.search(tail) and not token[0].isspace():
            if re.search(r'=\s*\w+\s*$', tail):
                return 'call_empty_collection'
            return 'call_collection'
        if COLLECTION.search(tail):
            return 'call_collection'
        if s.startswith(('>', '<>')):
            return 'call_generic'
        if re.search(r'(?:\bnew\s+\w+|::new|\.new)\s*$', tail):
            return 'call_constructor'
        if re.search(r'\bprint\s*$', tail):
            return 'call_print'
        return 'call_statement' if ';' in s or '\n' in token else 'call'
    elif ('""' in s or "''" in s) and not ('"""' in s or "'''" in s):
        kind = 'string'
        offset = min([i for i in (s.find('""'), s.find("''")) if i >= 0])
    else:
        m = WORD.fullmatch(s)
        if not m:
            return 'other'
        word = m[1]
        kind = word if word in ('None', 'nil', 'undefined') else word.lower()
        if kind in ('nullptr', 'none'):
            kind = 'null'
        offset = m.start(1)
    before = tail + token[:len(token)-len(token.lstrip())] + s[:offset]
    if re.search(r'(?<![=!<>])=\s*$', before):
        if kind == 'zero':
            lhs = re.search(r'([\w]+)\s*=\s*$', before)
            if lhs:
                name = re.sub(r'([a-z])([A-Z])', r'\1_\2', lhs[1]).lower()
                if ACCUMULATOR.search(name):
                    return 'zero_accumulator'
            code = bool(CODE.search(tail)) or ':=' in before[-4:]
            spaced = bool(before and before[-1].isspace())
            language = 'code' if code else 'plain'
            spacing = '_space' if spaced else ''
            return 'zero_assign_' + language + spacing
        if kind in ('list', 'dict'):
            if re.search(r':=\s*$', before):
                return kind + '_colon'
            if ';' in token:
                return kind + '_initial_statement'
            if '\n' in token:
                return kind + '_initial_line'
        return kind + ('_compact' if s.startswith('=') else '_assign')
    if re.search(r'\breturn\s*\(?\s*$', before):
        context = 'return'
    elif re.search(r':\s*$', before):
        context = 'colon'
    elif re.search(r'(?:[=!<>]=|[<>]|\bis(?: not)?)\s*$', before):
        context = 'test'
    elif re.search(r'[,;(\[]\s*$', before):
        context = 'arg'
    else:
        context = 'ordinary'
    if kind == 'zero' and context == 'ordinary':
        if tail and tail[-1].isdigit():
            return 'zero_digit'
        if tail.endswith('.'):
