    return kind + '_' + context


EXTRAS = {
    'other': -.002,
    'call': .52, 'call_statement': .75,
    'call_collection': 3.7, 'call_generic': 4.2,
    'call_empty_collection': 9.5,
    'list_initial_line': 9.3, 'list_initial_statement': 5.5,
    'dict_initial_line': 9.0, 'dict_initial_statement': 4.8,
    'zero_accumulator': 8.5,
    'call_constructor': 1.8, 'call_print': 2.6,
    'zero_ordinary': .04, 'zero_arg': .1, 'zero_test': .5,
    'zero_colon': .5, 'zero_return': 2.5,
    'zero_digit': -.02, 'zero_decimal': .24,
    'zero_assign_code': 2.5, 'zero_assign_code_space': 5.2,
    'zero_assign_plain': 1.05, 'zero_assign_plain_space': 1.7,
}
CONTEXTS = ('ordinary', 'assign', 'return', 'colon', 'test', 'arg')


def predict(token, tail):
    label = describe(token, tail)
    if label in EXTRAS:
        return EXTRAS[label]
    kind, context = label.rsplit('_', 1)
    if context == 'compact':
        return LEVELS[kind][1] * .55
    return LEVELS[kind][CONTEXTS.index(context)]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, tail)
    return (doc, (tail + token)[-240:]), float(value)

