"""Starting-value literals in code: a detector for `x = 0`, `x = null`, `x = []`.

Component layers.1.mlp.down_proj:2508 fires on the literal that source code uses as an
initial or default value: zero, null/None/NULL/nil, false, an empty list `[]`, or an
empty constructor `new Foo()`. The strongest case is a plain assignment (`int i = 0;`,
`String s = null;`, `items = []`, `flag = False`, `node.left = None`).
It is weaker after `return` and `:` (`return false`, `{"a": null}`), absent after
comparisons (`x == null`, `x is None`), and weak in prose (`x=0` in a math sentence).
Variables that count or accumulate (i, j, n, count, sum, total, ...) boost the zero case.
Everywhere else the prediction is 0.
"""

READS = ()

# How strongly each literal reads as a starting value.
STRENGTH = {
    "None": 8.0, "null": 8.0, "nullptr": 8.0, "NULL": 6.0, "[]": 8.0,
    "false": 6.0, "False": 6.0, "FALSE": 6.0, "0": 2.5,
    "true": 2.0, "True": 2.0, "nil": 1.5, "{}": 2.0, '""': 2.0, "''": 2.0,
}
# The token just before the literal, and how much it puts the literal in a value slot.
OPENER = {"=": 1.0, ":=": 1.0, "=>": 0.6, ":": 0.4, "return": 0.4}
COMPARE = {"is", "==", "!=", "not", "===", "!=="}
# Signs that the text is code rather than prose.
CODE_MARKS = (";", "{", "}", "int ", "var ", "let ", "const ", "def ", "self.")
COUNTERS = {"i", "j", "k", "n", "count", "sum", "total", "max", "min", "result",
            "index", "idx", "flag", "found", "margin", "len", "num", "cnt", "acc"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    literal = tokens[-1].strip().rstrip(";,")  # "0;" -> "0", "[];" -> "[]"
    value = 0.0
    if literal == "()" or literal == "<>()":  # empty constructor, e.g. "new Foo();"
        if _previous(tokens) == "new":
            value = 2.0
    elif literal in STRENGTH:
        before = _previous(tokens)
        weight = OPENER.get(before, 0.0)
        if weight and before not in COMPARE:
            value = STRENGTH[literal] * weight
            window = "".join(tokens[-40:])
            if not any(mark in window for mark in CODE_MARKS):
                value *= 0.5  # prose, e.g. "alpha=0"
            if literal == "0" and before == "=" and _name_before_equals(tokens) in COUNTERS:
                value *= 2.0
    return carry, float(value)


def _previous(tokens):
    """The last non-blank token before the newest one."""
    for s in reversed(tokens[:-1]):
        if s.strip():
            return s.strip()
    return ""


def _name_before_equals(tokens):
    """The identifier just before the '=' that precedes the newest token."""
    found_equals = False
    for s in reversed(tokens[:-1]):
        s = s.strip()
        if not s:
            continue
        if not found_equals:
            found_equals = s == "="
        else:
            return s
    return ""

"""Component p-82af68dd@100000/layers.1.mlp.down_proj:2509 (layer 1 MLP down-projection).

What it does: a negative detector for the German place-name ending "-burg" / "-berg"
when it appears as a word fragment. Its activation is near zero almost everywhere
(typical size about 0.05). It goes strongly negative on the token that spells the
ending of a "-burg" name: "burg" in Hamburg, Magdeburg, Lynchburg, Petersburg; "berg"
in surnames and place names such as Heidelberg-type names; "Berg" as a surname; "borg"
and so on. Weaker negative values come from look-alike fragments: "bug" / "bugs", then
"bury", "bach", "berry", "borough", then the fragments "erg", "urg", "rg", "gh".

Why: the program is a lookup on the current token's text, with no state. It says:
  -burg family: -6.2; -berg family: -4.6; bug: -3.0; b-word look-alikes: -1.6;
  erg/urg fragments: -0.9; anything else: 0.
The magnitudes are the family means measured on 24,000 training rows (12.3M positions).

What the simple version gets and misses: on held-out eval rows it explains about 26% of
the variance (r = 0.52), and it recovers about 30% of the output change that switching
the component off makes. The rest is mostly context: the same token varies a lot in
size (e.g. "berg" ranges from about -1 to -10, larger after names like "Sebastian" and
smaller after "gold"), plus a long diffuse tail of small values around 0.05 to 0.3 that
no short rule captures. A per-token lookup table over the 10,000 most frequent tokens
would reach about 0.43 in-sample; this program keeps only the concept.
"""

READS = ()

# Tokens that spell the "-burg" ending, the "-berg" family, and their look-alikes.
BURG = {"burg", "enburg", "ourg", "sburg", "burgh", "bourg"}
BERG = {"berg", "borg", "enberg", "berger", "burger", "ürger", "urger"}
BUG = {"bug", "bugs"}
LOOKALIKE = {"bury", "bach", "berry", "berries", "borough"}
FRAGMENT = {"erg", "urg", "rg", "gh", "egr"}


def step(carry, prefix, upstream):
    # The current token's text, decoded alone, lowercased, without its leading space.
    text = prefix.token_strings[-1].strip().lower()
    if text in BURG:
        value = -6.2
    elif text in BERG:
        value = -4.6
    elif text in BUG:
        value = -3.0
    elif text in LOOKALIKE:
        value = -1.6
    elif text in FRAGMENT:
        value = -0.9
    else:
        value = 0.0
    return carry, value

