"""A negative opening-context pulse, sustained through exact initial repeats.

Reset at each row or document boundary. Estimate the pulse's size using the
opening token's spelling class, English frequency, case and leading blank.
Question openers, articles, digits, module keywords and headings are stronger.
Predict zero after the first different token; omit small later fluctuations
and irregular token-specific differences rather than storing a token table.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
QUESTION_WORDS = frozenset({
    'what', 'how', 'when', 'where', 'why', 'who', 'which', 'whom', 'whose',
})
AUXILIARIES = frozenset({
    'am', 'is', 'are', 'was', 'were', 'be', 'do', 'does', 'did',
    'have', 'has', 'had', 'can', 'could', 'will', 'would',
    'shall', 'should', 'may', 'might', 'must',
})


@lru_cache(maxsize=8192)
def start_value(text):
    word = text.strip()
    if text == '<|endoftext|>':
        return -15.2
    if text.startswith('<|'):
        return -3.2
    if not word:
        if '\n' in text or '\r' in text:
            return -3.4
        return -8.2 if text == '\t' else -5.5
    if '\ufffd' in word:
        return -2.3
    if word.isascii() and word.isdecimal():
        if word == '0':
            return -30.9
        if word == '2':
            return -19.2
        return -7.0 if word in {'1', '9'} else -11.2
    # Module declarations and imports often occur at the start of source files.
    if text in {'import', 'from', 'package'}:
        return -16.7
    if word.isascii() and word.isalpha():
        space = text.startswith(' ')
        lower = word.lower()
        if lower in QUESTION_WORDS:
            what_or_how = lower in {'what', 'how'}
            if word.istitle() and not space:
                return -36.0 if what_or_how else -19.0
            if word.istitle():
                return -24.0 if what_or_how else -9.0
            return -16.0 if what_or_how else -7.0
        commonness = max(0.0, zipf_frequency(word.lower(), 'en') - 4.5)
        value = -5.7 + 2.3 * space - 1.5 * (len(word) == 1)
        value += 1.4 * (word.isupper() and len(word) > 1)
        value -= commonness * (1.65 + 0.83 * word.istitle() - 0.33 * space)
        if word.lower() in {'a', 'an', 'the'}:
            value -= 1.7
        if word.lower() == 'a':
            value -= 7.3
        if word.istitle() and not space and lower in AUXILIARIES:
            value -= 4.5
        return value
    if set(word) == {'#'}:
        return -17.1 if len(word) == 1 else -10.7
    if word.startswith('#'):
        return -7.5
    if '\n' in text:
        if word == '.' and text.count('\n') == 1:
            return -4.35
        return -1.8
    if word == '.':
        return -8.9
    if word == ',':
        return -10.5
    return -4.3


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = start_value(prefix.token_strings[-1])
        return (document, token, value), value
    _, first_token, value = carry
    if token != first_token:
        value = 0.0
    return (document, first_token, value), value

