"""Layer-1 MLP neuron-direction 2510 (down_proj): a first-token-of-document detector.

It is negative on the first token of each document (the first token of a row, or the first
token after a document break). It also stays negative through a run of one repeated token
that starts the document (a document made only of '0 0 0 ...', or of middle dots), since
then the model reads the run the same way it reads a lone first token. Everywhere else in a
document it is about 0.

The size of the negative value depends only on which token it is:
  * '0', and the capitalised question openers What, How, Can, When, Is: strongly negative
    (-30);
  * other question and sentence-opening words (what, The, In, For, I, This, ...), the
    article 'A' or 'a' and ' a', '#', and code keywords (import, package, ...): negative (-16);
  * digits 1-9, capital letters, ' the', the middle-dot leader '··': moderately negative (-10);
  * capitalised words, punctuation and other symbols: mildly negative (-6);
  * everything else, including '<|im_start|>' and newlines: slightly negative (-4.5).
"""
import re

READS = ()

OPENERS = set("what how when can could would should do does did is are was were am will "
              "which who why where if as for after given this we in on the a an i my one two "
              "three four five six seven eight nine".split())
CAPITAL_OPENERS = {"What", "How", "Can", "When", "Is"}
CODE = set("import package public private def const class include return var uint unsigned "
           "function".split())


def strength(tok):
    x = tok.strip()
    low = x.lower()
    bare = tok[:1] != " "
    if x == "0" or (bare and x in CAPITAL_OPENERS):
        return -30.0
    if x == "#" or low in CODE or (bare and low in OPENERS):
        return -16.0
    if re.fullmatch(r"[1-9]", x) or (not bare and low in OPENERS) or re.fullmatch(r"[A-Z]", x) or x == "··":
        return -10.0
    if re.fullmatch(r"[A-Z][a-z]+", x) or re.fullmatch(r"[^\w\s]+", x):
        return -6.0
    return -4.5


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    start = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if start:
        first, uniform = tok, True
    else:
        first, uniform = carry[0], carry[1] and tok == carry[0]
    return (first, uniform), (strength(tok) if uniform else 0.0)

