        elif before.endswith(('"', "'", '\\n')):
            value = -0.6
        if position == 0:
            value = -6.08
    elif word == 'void':
        if newline:
            value = -2.6 - 1.6 * early - 0.7 * includes
            if '}' in previous:
                value = -4.1
        elif re.search(r'\bstatic\s*$', before):
            value = -3.4 - 2.5 * early
        elif whitespace or first or numbered:
            value = -2.1
        else:
            value = -0.7
    elif word == 'int':
        if newline:
            value = ((-6.6 if braces <= 0 else -2.3) if includes
                     else -1.1 - 2.7 * early)
        elif first or numbered:
            value = -0.8
        elif includes:
            value = -1.4 if position < 128 else -0.25
        if position == 0:
            value = -0.77
    elif word == 'class':
        value = -1.2 - 2.4 * early if newline else -0.3 if numbered else 0.0
        if position == 0:
            value = 1.24
    elif word == 'namespace':
        value = -3.2 if first else -1.8 if previous.strip() == 'using' else 0.0
    elif word == 'impl':
        value = -2.25 if first else 0.0
    elif word in SMALL_TYPES:
        value = (SMALL_TYPES[word] if newline
                 else SMALL_TYPES[word] * 0.3 if first else 0.0)
    elif word == 'char' and includes:
        value = -0.8
    elif word in {'fn', 'func', 'function'}:
        value = (-0.4 if first or previous.strip() in {'async', 'pub', 'export'}
                 else 0.0)
    elif word == 'main':
        if includes:
            value = -5.8
        elif previous.strip() in {'int', 'void', 'func'} or first:
            value = -0.65
    elif word == 'using' and includes:
        value = -1.15
    elif word == 'break':
        if whitespace or first or numbered:
            value = 0.8 + 0.6 * early
    elif word == 'print':
        value = 0.3 if first else 0.15 if whitespace else 0.0

    # Recognize the ends of import/include statements, not prose line breaks.
    if word == '.h' and '#include' in line:
        value = -1.9 if line.endswith('stdio') else -0.35
    elif '\n' in token:
        if '#include' in line and word in {'>', '"'}:
            value = -1.7 if token.count('\n') > 1 else -0.9
        elif re.match(r'\s*using\s+namespace\s+', line) and ';' in token:
            value = -2.7 if token.count('\n') > 1 else -1.0
        elif re.match(r'\s*(?:import|from|using)\b', line):
            value = -0.65 if token.count('\n') > 1 else -0.1
    if position == 0 and word == 'Q':
        value = -0.7
    elif position == 1 and previous in {'Q', 'Title'} and token.startswith(':'):
        value = 1.85
    elif len(word) >= 2 and not word.strip('·'):
        value = 1.72

    carry = (doc, (line + token).split('\n')[-1][-120:],
             (recent + token)[-600:], token, position + 1,
             braces + token.count('{') - token.count('}'))
    return carry, float(value)

"""Negative pulses at document ends and, more weakly, long paragraph ends.

An end-of-text separator has a stronger negative response later in a document;
line breaks and non-ASCII text soften it. An isolated separator is positive.
It also recognizes conversation/title headers, escaped indentation, and dotted
separators. Other ordinary tokens are zero. State resets at document boundaries.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', (), 0)
    _, position, previous, recent, paragraph_length = carry

    value = 0.0
    if text == '<|endoftext|>':
        if position == 0:
            value = 1.265
        else:
            nonascii_rate = sum(not t.isascii() for t in recent) / len(recent)
            value = (-2.45 - 0.21 * math.log1p(position)
                     + 1.1 * ('\n' in previous)
                     + 0.8 * nonascii_rate)
    elif text.count('\n') >= 2:
        # A sentence-ending blank line after a long uninterrupted paragraph.
        if '.' in text:
            value = -0.0015 * max(0, paragraph_length - 128)
        elif not text.strip():
            value = -0.0003 * max(0, paragraph_length - 128)

    # Fixed-format boundary and indentation markers.
    if position == 0 and text == '<|im_start|>':
        value = 0.234
    elif position == 1 and previous == 'Title' and text == ':':
        value = -2.16
    elif text == r'\t' and (position == 0 or
                             (position == 1 and previous == r'\t')):
        value = 2.706
    elif text == '··':
        value = 0.50

    if text.count('\n') >= 2:
        paragraph_length = 0
    return (doc, position + 1, text, (recent + (text,))[-64:],
            paragraph_length + 1), value

"""Formatting and document-opening heuristics, not a content-word model.

Chat/tool boundaries and paragraph breaks have small signed responses. The
opening token (including an initial run of identical tokens) can be stronger:
indefinite articles are positive, negators and indentation mostly negative.
Unmatched ordinary tokens contribute zero. Token case and leading blanks
matter for the document-opening articles.
"""
READS = ()

MARKERS = {
    '<think>': -0.04, '</think>': 0.09,
    '<|im_start|>': 0.01, '<|im_end|>': 0.068,
    '<tool_response>': 0.082, '</tool_response>': 0.095,
    '<tool_call>': 0.049, '</tool_call>': 0.027,
}
PUNCTUATION = {
    "'": 0.021, '!': -0.06, ':': 0.014, ')': 0.014,
    '•': 0.062, '…': 0.12, '=': -0.015,
    '===': -0.084, '$$': -0.079, '__': 0.039,
}
NEGATORS = {'no', 'not', 'never', 'none'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, opening = '', True
    else:
        _, previous, opening = carry
        opening = opening and s == previous
    w = s.strip()
    lower = w.lower()
    value = MARKERS.get(s, PUNCTUATION.get(w, 0.0))
    if s == '\n\n':
        value = {'<think>': 0.16, '</think>': 0.09}.get(previous, 0.035)
    elif s == '\n':
        value = {'assistant': 0.014, 'user': 0.0,
                 '<|im_end|>': -0.041}.get(previous, -0.016)
    elif '\n' in s and (not w or w in {'.', ':'}):
        value = -0.04 if s.endswith('\n\n') else -0.016
    elif '\xa0' in s:
        value = -0.30 if previous.count('\xa0') >= 2 else -0.023
    elif '\t' in s and s.isspace():
        value = 0.05 if ' ' in s else -0.01
    elif s == 'assistant' and previous == '<|im_start|>':
        value = -0.031
    elif lower in NEGATORS:
        value = -0.025
    elif w == '#':
        value = 0.01 if s.startswith(' ') else 0.05
    if opening:
        value = -0.01 if s.startswith(' ') else -0.10
        if lower == 'an':
            value = 2.21 if s == 'An' else 1.49 if s == ' an' else 0.89
        elif lower == 'a':
            value = 0.08 if s in {'a', ' A'} else 0.30
        elif lower == 'the':
            value = 0.71 if s == ' The' else -0.07
        elif lower in {'no', 'not'}:
            value = -0.9 if lower == 'not' else -0.35
        elif s == '\t':
            value = -1.03
        elif s == ' ':
            value = 0.114
        elif s == '\n':
            value = 0.21
        elif not w:
            value = -0.3 if s.isspace() and '\n' not in s else -0.14
        elif w.isdigit():
            value = -0.15
        elif w == '(':
            value = 0.40 if s.startswith(' ') else 0.075
        elif w == ')':
            value = -0.24
        elif w in {'"', '"""'}:
            value = -0.55
        elif w == '··':
            value = -1.885
    return (doc, s, opening), value

"""Mostly a detector for English 'all' phrases, especially 'all you/I/that'.

Clause-opening pronouns after 'all' give a large positive value, larger after
capitalized 'All'. 'All this' and several common idioms are weaker; 'all right',
'all three', and pronouns in 'all of these/them' give negative values. Whitespace
may intervene. There is also a separate response to familiar library-name
suffixes and the Unix /local/lib path. A smaller pronoun response follows
'what'. Everything else is nearly zero.
"""

READS = ()
SUBJECTS = frozenset(('i', 'you', 'he', 'she', 'it', 'we', 'they'))
POSSESSIVES = frozenset(('my', 'your', 'his', 'her', 'its', 'our', 'their'))
SUPERLATIVES = frozenset(('first', 'last', 'most', 'least', 'best', 'worst'))
LIBRARIES = {'stdlib': 4.5, 'mslib': 4.3, 'pvlib': 2.6, 'glib': 1.5}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, last, before, gap = carry
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower()
    previous = last.lower()
    earlier = before.lower()
    capital = last == 'All'
    value = -0.002

    if previous == 'all':
        if word in SUBJECTS:
            if capital:
                value = 7.6
            else:
                value = 6.8 if word in ('you', 'we', 'it') else 5.0
            if not raw[:1].isspace() and not gap:
                value *= 0.5  # A joined identifier is weaker than a phrase.
        elif word == 'that':
            value = 4.8 if gap else (7.3 if capital else 5.0)
        elif word == 'this':
            value = 2.3 if capital else 1.2
        elif word in ('one', 'there', 'is', 'was'):
            value = 2.7
        elif word == 'else':
            value = 1.7
        elif word == 'right':
            value = -2.0 if capital else -1.1
        elif word == 'three':
            value = -1.1
        elif word in ('day', 'kinds', 'sorts', 'while', 'or'):
            value = 1.5
        elif word in ('are', 'were'):
            value = -0.8
        elif word == 'the':
            value = -0.23
        elif word == 'of':
            value = -0.1
        elif word in POSSESSIVES:
            value = 0.4
        elif word.isdecimal():
            value = 1.7 if capital else 0.5
        elif not word:
            value = 0.9 if capital else 0.37
        if last == 'ALL' and value > 1:
            value *= 0.55
    elif earlier == 'all':
        if previous in ('day', 'year') and word == 'long':
            value = -3.0
        elif previous == 'of':
            if word == 'these':
                value = -0.95
            elif word in ('them', 'it', 'those'):
                value = -0.6
            elif word in ('you', 'which'):
                value = -0.35
    elif word == 'all' and previous == 'of' and earlier in SUPERLATIVES:
        value = -0.9
    elif previous == 'what' and word in SUBJECTS:
        value = 0.25

    if text == '/lib' and last.endswith('/local'):
        value = 1.3
    elif text == 'lib':
        joined = (before + last + text).lower()
        for name, response in LIBRARIES.items():
            if joined.endswith(name):
                value = response
                break

    # Remember words across at most one whitespace-only token, not a long gap.
    if not text and gap == 0:
        return (doc, last, before, 1), float(value)
    return (doc, text, last, 0), float(value)

"""A local Roman-numeral/letter-I detector, with a separate response to ions.

Number labels are strongest at a following full stop or closing parenthesis.
A bare I is usually a pronoun, and i in an identifier is usually not a number.
Runs of middle dots have a separate negative response. The ion rule also
recognizes its Japanese spelling. All other text is predicted near zero.
These short-context rules approximate, rather than fully explain, the component.
"""
import re

READS = ()
ROMAN = re.compile(r'[IVX]+|[ivx]+')
LABELS = {
    'type', 'class', 'phase', 'division', 'group', 'stage', 'section',
    'chapter', 'volume', 'book', 'part', 'title', 'appendix', 'factor',
    'grade', 'level',
}


def numeral(s):
    s = s.strip().lstrip('([.-')
    return s if ROMAN.fullmatch(s) else ''


def predict(s, p, pp):
    word = s.strip()
    r = numeral(p)
    n = numeral(s)
    labelled = pp.strip().lower() in LABELS
    line_start = not pp or ('\n' in pp and not pp.split('\n')[-1].strip())
    opened = ('(' in p or pp.rstrip().endswith('(')
              or ('(' in pp and numeral(pp)))
    if len(word) >= 2 and set(word) == {'·'} and (not p or p == s):
        return -2.24
    if r:
        if re.fullmatch(r'\.[\s\\]*', s):
            if line_start:
                return 3.4 if r != 'x' else 0.0
            if len(r) > 1:
                return 1.25
            return {'I': 0.8, 'i': 0.12, 'v': 0.45, 'V': 0.5}.get(r, 0.0)
        if s == ')':
            if len(r) > 1:
                return 3.0 if opened or line_start else 0.7
            if r in ('I', 'i'):
                boundary = not pp or pp[-1:].isspace() or pp[-1:] in ':;,.'
                enumeration = (pp == ' ('
                               or (p.startswith(('(i', '(I')) and boundary))
                return 2.6 if enumeration else 0.1
        if s[:1].isalpha() and s.isascii():
            if r == 'I':
                if s[0].islower():
                    return 0.5
                if len(s) > 1 and s[1:].islower():
                    return -1.0
            if len(r) > 1 and labelled:
                return 2.5
        if s.startswith(':') and opened and r == 'I':
            return 2.8
        if s.startswith('-') and (r == 'I' or len(r) > 1):
            return 3.0 if labelled else 0.5
    if n:
        opened_now = '(' in s or p.rstrip().endswith('(')
        if len(n) > 1:
            if opened_now:
                return 2.1
            if p.strip().lower() in LABELS:
                return 1.25
            return 0.24 if s[:1].isspace() else 0.04
        if n == 'I':
            if p.strip().lower() in LABELS:
                return 1.6
            return 0.7 if opened_now else 0.04
        if n == 'i' and opened_now:
            return 0.26
    if re.fullmatch(r'[- ]?[Ii]on(?:s|ic)?', s):
        if (s.startswith((' ', '-')) or not p or p[-1:].isspace()
                or p.endswith(('(', '-'))):
            return 2.3
    if word.startswith('I') and word[1:] in ('A', 'B'):
        return 2.7 if p.strip().lower() in LABELS else 0.3
    if word == 'オン' and p.strip() == 'イ':
        return 1.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p = pp = ''
    else:
        _, p, pp = carry
    s = prefix.token_strings[-1]
    return (doc, s, p), predict(s, p, pp)

programs.haiku:
READS = ()

# Roman numerals written as labels: "(ii)", "III.", "Type II", "copper(II)".
MULTI = {"ii", "iii", "iv", "vi", "vii", "viii", "ix", "xi", "xii", "xiii", "xiv", "xv"}
UPPER = {"I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV", "XV"}
# single lowercase letters are numerals only inside brackets: "(i)", "(v)"; "(x)" is usually algebra
SINGLE = {"i", "v"}
# words that introduce a numbered division: "Type II", "Phase III", "Chapter IV"
NUMBERED_NOUNS = {"type", "phase", "chapter", "volume", "title", "class", "division", "stage", "part"}


def numeral(s):
    """The Roman numeral a token spells, ignoring a leading '(' or '-' and a trailing ')' or ':'."""
    return s.strip().strip("(-:)[").strip()


def step(carry, prefix, upstream):
    s = prefix.token_strings
    n = len(s)
    if n < 2:
        return None, 0.0
    cur, prev = s[-1].strip(), s[-2]
    pp = s[-3] if n >= 3 else ""
    num = numeral(prev)
    # 1. the ')' or '.' that closes a numbered label: "(ii)", "(i)", "III."
    if cur in {")", "."}:
        opened = prev.lstrip().startswith("(") or pp.strip() == "("
        if num in MULTI or num in UPPER:
            if opened:
                return None, 3.3 if num in MULTI else 1.9
            if pp.strip() == "" or "\n" in pp:
                return None, 3.5
            return None, 1.2
        if num in SINGLE and opened and cur == ")" and (pp.endswith(" ") or "\n" in pp or pp.strip() == "("):
            return None, 3.0
        return None, 0.0
    # 2. the numeral itself: "(ii" in a list, or after a numbered-division word ("Type II")
    if numeral(cur) in MULTI and (prev.strip() == "(" or cur.startswith("(")):
        return None, 2.2
    if numeral(cur) in UPPER and prev.strip().lower() in NUMBERED_NOUNS:
        return None, 2.0
    if numeral(cur) in UPPER and prev.strip() == "(":
        return None, 1.0
    # 3. the word "ion" (chemistry: hydrogen ion, lithium-ion)
    if s[-1] in {" ion", " Ion", "-ion", " ions"}:
        return None, 2.0
    return None, 0.0

programs.sol:
"""Approximate a detector of non-sentence dots.

Periods after numbers, initials and list labels are positive; ordinary word
endings are nearly zero. Numeric points are stronger in version, currency,
non-ASCII-word and recently decimal-rich contexts. Later dots in dotted
numbers are weaker. A few other dot-like separators and line endings have
small rules of their own. Unix working/installation directory names also
have positive path signals. State is just a short, document-local suffix.
"""
import re

READS = ()
# Directory names are only recognized as path segments, not as ordinary words.
PATH_DIRECTORIES = {
    'workspace': 0.70, '/workspace': 0.19,
    'usr': 0.39, 'local': 0.70, '/local': 0.70,
    'opt': 0.74, 'etc': 0.29,
    'tmp': 0.40, 'home': 0.80, 'root': 0.42,
    'lib': 0.21, '/lib': 0.21,
}


def numeric_point(digits, left):
    n = len(digits)
    if n == 1:
        value = 1.32 if digits == '0' else 1.14 if digits == '1' else 0.93
    else:
        value = 0.66 if n == 2 else 0.48 if n == 3 else 0.40
    if n == 4 and 1000 <= int(digits) <= 2100:
        value -= 0.27  # Year-like integers seldom introduce a fraction.
    last = left[-1:]
    if last in ('v', 'V'):
        value += 0.73  # A version prefix.
    elif last and last.isalpha():
        value += 1.31 if not last.isascii() else -0.39
    if last and last in '$€£¥₹':
        value += 0.62
    if left.endswith('__'):
        value += 0.39  # Versioned checkout names.
    if left[-80:].count('/') >= 2:
        value += 0.29  # Path-like context.
    if left.rstrip().endswith(('=', '^', '<', '>', '≤', '≥', '≠')):
        value -= 0.10
    if last and last in '([':
        value += 0.24
    if last and last in ',:':
        value -= 0.16
    if re.search(r'\d\.\d', left[-80:]):
        value += 0.52  # Nearby text has already used decimal notation.
    return max(-0.1, min(3.5, value))


def period(before):
    number = re.search(r'\d+$', before)
    if number:
        digits = number[0]
        left = before[:number.start()]
        if left.endswith('.'):
            return 0.57 if len(digits) == 1 else 0.28
        if re.search(r'(?:^|\n)[ \t*-]*$', left):
            return 1.28 if digits == '0' else 0.74
        return numeric_point(digits, left)

    word = re.search(r'[^\W\d_]+$', before)
    if not word:
        return -0.05
    letters = word[0]
    left = before[:word.start()]
    if len(letters) == 1:
        if re.search(r'[^\W\d_]\.$', left):
            return 0.16  # A subsequent initial, as in U.S.
        if re.search(r'(?:^|\n)[ \t*]*$', left):
            return 0.78  # A letter used as a list label.
        if letters.isupper():
            preceding = re.search(r'([^\W\d_]+)\s+$', left)
            return 0.94 if preceding and preceding[1].istitle() else 0.61
        return 0.13 if letters.islower() else 0.0
    if letters.isupper() and re.fullmatch('[IVXLCDM]+', letters):
        return 0.39
    return 0.18 if left.endswith(('[', '(', '.')) else 0.0


def predict(token, before):
    if token in PATH_DIRECTORIES and (token.startswith('/') or before.endswith('/')):
        return PATH_DIRECTORIES[token]
    if token == '/' and re.search(r'/opt$', before):
        return 0.50
    if token == '.':
        return period(before)
    if token in ('·', '・', '･'):
        if not before.rsplit('\n', 1)[-1].strip():
            return -0.15  # A bullet at the start of a line.
        last = before[-1:]
        if last.isalpha() and not last.isascii():
            return 1.67 if token == '·' else 0.45
        return 0.15
    if len(token) > 1 and not token.strip('·'):
        return -1.76
    if token == '、' and re.search('[一二三四五六七八九十百零〇两壹贰叁]+$', before):
        return 0.73
    if token in (' \n', '  \n'):
        return 0.11
    if token == '.\n':
        return 0.02
    if token == '.\n\n':
        return -0.02
    if token.endswith('\n\n\n'):
        return 0.54 if token[0] in '.:' else 0.14
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    before = tail.decode('utf-8', errors='ignore')
    value = predict(prefix.token_strings[-1], before)
    tail = (tail + prefix.token_bytes[-1])[-256:]
    return (doc, tail), value

programs.haiku:
"""Tone-marked romanisation inside Chinese text (candidate v7).

The component reads Latin letters with a tone mark, as used to romanise Chinese (pinyin):
the caron vowels ǎ ǐ ǒ ǔ ǚ, the macrons ā ē ī ō ū, and the acute and grave marks
á é í ó ú à è ì ò ù. It responds when Chinese characters appear shortly before in the same
document: the tone-marked letter itself (strongly), and the plain-Latin syllable right
after it (the rest of the romanised word). Outside Chinese text, only the caron vowels
still respond a little. Two further rules: the first token of each document is pushed
slightly negative, and a run of middle dots '··' strongly negative.
"""

READS = ()

CARON = set("ǎǐǒǔǚǖǘǜ")
MACRON = set("āēīōū")
ACUTE_GRAVE = set("áéíóúàèìòùńňǹḿ")
TONE = CARON | MACRON | ACUTE_GRAVE
DOT_RUN = "··"
WINDOW = 12


def is_cjk(s):
    return any("一" <= c <= "鿿" for c in s)


def has(s, marks):
    return any(c in marks for c in s)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1]
    if cur == DOT_RUN:
        return None, -1.2
    if len(toks) == 1 or docs[-1] != docs[-2]:
        return None, -0.22
    # the previous WINDOW tokens of this document, nearest last
    before = [s for s, d in zip(toks[-WINDOW - 1:-1], docs[-WINDOW - 1:-1]) if d == docs[-1]]
    cjk = any(is_cjk(s) for s in before)
    if has(cur, CARON):
        return None, 3.5 if cjk else 1.8
    if has(cur, MACRON):
        return None, 2.5 if cjk else 0.0
    if has(cur, ACUTE_GRAVE):
        return None, 3.5 if cjk else 0.0
    if cjk and cur.isascii() and cur.isalpha():
        if before and has(before[-1], TONE):
            return None, 2.1
        if len(before) > 1 and has(before[-2], TONE):
            return None, 0.5
    return None, 0.0

programs.sol:
"""An opening-token pulse with coarse grammatical and shape adjustments.

The component is much stronger at document openings than later. This
approximation adds a few calibrated effects there: pronouns and long
space-prefixed tokens lower the pulse; indefinite articles and indentation
raise it. Digits, punctuation, control tokens and writing system also
adjust it. Individual opening words vary much more than these rules explain.
"""
import regex

READS = ()
THIRD_PERSON = frozenset(
    'he him his she her hers it its they them their theirs'.split()
)
PREPOSITIONS = frozenset(
    'of to in for on with at from by about as into like through after over '
    'between out against during without before under around among'.split()
)


def opening_pulse(token):
    text = token.strip()
    word = text.lower()
    spaced = token.startswith(' ')
    value = -1.61

    # Token shape and writing system.
    if spaced:
        value -= 0.57
    if spaced and len(text) >= 8:
        value -= 1.28
    if text.isdigit():
        value -= 1.28
    if len(token) > 1 and token.strip(' ') == '':
        value += 3.35
    if not token.isascii():
        value += 0.64
    if regex.search(r'\p{Script=Cyrillic}', token):
        value += 1.39
    if text.startswith('<|'):
        value += 0.94
    if regex.fullmatch(r'\p{P}+', text):
        value += 0.59
    if text == '#':
        value -= 2.64

    # Broad English grammatical classes, not individual-word lookups.
    if word in THIRD_PERSON:
        value -= 3.74
    if word in {'a', 'an'}:
        value += 2.78
    if word in PREPOSITIONS:
        value += 1.28
    if word in {'this', 'that', 'these', 'those'}:
        value -= 1.74
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = opening_pulse(prefix.token_strings[-1]) if first else 0.0
    return document, value

"""Approximate an O-initial word-fragment detector.

The main response is to letter continuations of words beginning with Latin O
(including accents), Cyrillic о, Greek omicron, or the Japanese/Korean o syllable.
The response is strongest near the beginning of a short fragment and tapers
after four letters. Dictionary
frequency, capitalization, and script distinguish kinds of fragments. There is
also a smaller response to early digits of zero-leading numbers. State holds
only the unfinished word/number and the previous token, and resets per document.
CamelCase capitals start a new word inside an identifier.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LETTERS_AT_END = re.compile(r'[^\W\d_]+$')
CAMEL_BOUNDARY = re.compile(r'(?<=[a-z])(?=[A-Z])')


def o_script(word):
    if not word:
        return 0
    c = word[0].lower()
    if c == 'о':
        return 2  # Cyrillic
    if c in 'おオ':
        return 3  # Japanese o syllable
    if unicodedata.normalize('NFD', c).startswith('오'):
        return 3  # Hangul silent onset + o vowel
    if c in 'οό':
        return 4  # Greek omicron
    if unicodedata.normalize('NFD', c)[0] == 'o' or c == 'ø':
        return 1
    return 0


@lru_cache(maxsize=100000)
def frequency(word):
    language = 'ru' if any('а' <= c.lower() <= 'я' for c in word) else 'en'
    return zipf_frequency(word, language) if word else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, '', '', 0)
    _, word, pieces, number, previous, position = carry
    token = prefix.token_strings[-1]
    text, prev = token.strip(), previous.strip()
    cf, pf = frequency(text), frequency(prev)
    if token[:1].isupper() and word[-1:].islower():
        word, pieces = '', 0
    group = o_script(word) if token[:1].isalpha() else 0
    old_length = len(word)
    # An o-syllable token can introduce a local fragment, particularly in
    # Japanese writing without spaces.
    if o_script(prev) == 3 and token[:1].isalpha():
        group, old_length = 3, len(prev)

    value = 0.002
    if group:
        if old_length > 4:
            value = 1.4 if o_script(prev) == 2 else (0.7 if pieces <= 2 else 0.3)
        elif len(prev) > 2:
            value = 1.9 if len(text) <= 2 else 1.1
        elif o_script(prev) > 1:
            value = 3.3 if pf > 3.3 else 1.6
        elif prev.isupper():
            value = 3.9 if cf < 2.1 else 2.6
        elif text.istitle():
            value = 0.2
        elif cf > 3.5:
            value = 2.4 if old_length <= 3 else 1.4
        else:
            value = 0.8 if pf < 3.0 else 1.8
    elif (token[:1].isspace() or not word) and o_script(text):
        script = o_script(text)
        if script == 1:
            if cf < 4.1:
                value = 1.0 if text.isupper() else (0.7 if text.istitle() else 0.35)
            else:
                value = 0.13 if cf < 5.9 else 0.0
        elif script == 2:
            value = 2.4 if cf < 4.3 else (0.8 if cf < 6.1 else 0.15)
        else:
            value = 0.5

    digit = len(token) == 1 and token in '0123456789'
    if digit:
        if number == '0.0':
            value = 1.5
        elif len(number) == 3 and number.startswith('0.'):
            value = 0.35 if number[-1] == '1' else -0.4
        elif number.startswith('0.') and 4 <= len(number) <= 6:
            value = 0.4 if number[-1] == '0' else -0.3
        elif number == '00':
            value = 0.7 if token != '0' else 0.0
        elif number.startswith('00') and len(number) == 3 and number[-1] != '0':
            value = -0.5
    if position == 0:
        value = -0.14

    tail = LETTERS_AT_END.search(token)
    if tail:
        if tail.start() == 0 and word:
            word, pieces = word + tail.group(), pieces + 1
        else:
            word, pieces = tail.group(), 1
    else:
        word, pieces = '', 0
    split_word = CAMEL_BOUNDARY.split(word)
    if len(split_word) > 1:
        word, pieces = split_word[-1], 1
    if digit:
        number += token
    elif token == '.' and number and '.' not in number:
        number += '.'
    else:
        number = ''
    return (doc, word[-80:], pieces, number[-80:], token, position + 1), value

"""Approximate a mostly negative response to naming vocabulary.

The words 'name' and 'names' are especially negative in personal-name
labels. Code identifiers are weaker; 'function name' reverses the sign.
Additional rules cover Chinese naming words, zodiac suffixes, start/end-
with phrases, middle-dot separators, and fullwidth colons after bold marks.
These are lexical rules, not recognition of actual people's names.
Constants summarize training responses, except the bold-colon rule,
which comes from the harvest. Unmatched tokens predict zero.
"""
import re

READS = ()
ZODIAC = re.compile(
    r'(白羊|牡羊|金牛|双子|雙子|巨蟹|狮子|獅子|处女|處女|'
    r'天秤|天蝎|天蠍|射手|摩羯|魔羯|水瓶|双鱼|雙魚)$'
)
TECHNICAL = re.compile(
    r'\b(variable|file|class|method|module|parameter|argument|attribute|'
    r'column|table|field|index|database|directory|package|key|type|user)s?\s*$'
)


def predict(token, recent, previous):
    s = token.strip()
    lower = s.lower()
    context = recent.lower()
    if lower in ('name', 'names', 'named', 'naming', '_name', '-name'):
        if s == 'NAME':
            return -0.53
        if lower == 'named':
            return -0.75
        if lower == 'naming':
            return -0.01
        if lower == '-name':
            return 2.15 if context.endswith('function') else 0.23
        if lower == '_name':
            return -0.46
        if not token[:1].isspace():
            return -0.27
        if re.search(r'\bfunction\s*$', context):
            return 0.67
        if TECHNICAL.search(context):
            return -0.27
        if re.search(r'\((given|first|last|personal)\s*$', context):
            return -4.45
        if re.search(r'\b(first|last|maiden)\s*$', context):
            return -3.74
        if re.search(r'\bgiven\s*$', context):
            return -2.74
        if re.search(r'\bfamily\s*$', context):
            return -2.12
        if re.search(r'\bpersonal\s*$', context):
            return -3.0
        if re.search(r'\bthe\s*$', context):
            return -2.68
        if re.search(r'\b(my|your|his|her|its|our|their)\s*$|[’\']s\s*$', context):
            return -1.5
        if re.search(r'\b(to|by)\s*$', context):
            return -0.85
        if re.search(r'[=,{:]\s*$', context):
            return -0.48
        return -1.42 if lower == 'names' else -1.07
    if lower in ('surname', 'surnames'):
        return -0.43
    if s in ('名字', '的名字', '姓名'):
        return -2.48
    if s in ('名称', '名稱', '命名', '名为', '名為'):
        return -0.96
    if s == '名':
        return -0.71
    if s == '叫':
        return -0.51
    if s == '座' and ZODIAC.search(recent):
        return -4.33
    if s and set(s) == {'·'} and len(s) >= 2:
        return -0.92
    if lower in ('with', '_with'):
        if re.search(r'(start|starts|starting|begin|begins|beginning)\s*$', context):
            return -0.98
        if re.search(r'(end|ends|ending)\s*$', context):
            return -0.97
    if s == '：' and previous.strip() == '**':
        return -1.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '')
    _, history, previous = carry
    recent = history.decode('utf-8', errors='replace')[-160:]
    token = prefix.token_strings[-1]
    value = predict(token, recent, previous)
    history = (history + prefix.token_bytes[-1])[-512:]
    return (doc, history, token), value

programs.haiku:
"""Component layers.1.mlp.down_proj:2521 as a "name" word detector.

What it does: it goes strongly negative on the word "name" when the word means a
person's or thing's proper name, and only weakly negative when "name" is a code
identifier or a label in a technical context. Everything else is about 0.

Rules, in plain terms:
  * " name" / " names" in ordinary English prose:
      - after a name-making word ("given name", "first name", "family name",
        "domain name", "household name"): strongly negative (about -3.4);
      - after a determiner or possessive ("the name", "her name", "a good name"):
        about -2.0;
      - after any other word: about -1.0;
      - after punctuation or a symbol (e.g. "(name", "=name"): about -0.6.
  * after a code-ish word ("param name", "column name", "function name"): about 0.
  * " named" / "名字" / "名称" and friends: about -0.8 to -1.0.
  * " NAME" / " Name" and bare "name" / "_name" (identifiers): about -0.3 to -0.5.
  * " with" after "starting / starts / start / ends / begin" ("names that start
    with"): about -1.2, the same "naming" theme.
  * " of" right after "name" ("the name of"): about +0.6.

The numbers are the means of each group on 4096 training rows; the program does not
use any table of token ids beyond these word lists.
"""

READS = ()

NAME_WORDS = {" name", " names"}
NAMED_WORDS = {" named", " Named"}
CAPS_NAME = {" NAME", " Name", "NAME", "Name"}
CODE_NAME = {"name", "_name", "-name"}
ZH_NAME = {"名字", "名称", "姓名", "名为", "命名", "命名为", "名叫", "名"}
START_WORDS = {" starting", " starts", " start", " ends", " begin", " Starting", " beginning", " end"}

# words before "name" that make it a person's/thing's proper name
NAMING_WORDS = {
    "given", "first", "last", "family", "maiden", "personal", "middle", "full", "real",
    "stage", "pen", "nick", "screen", "birth", "brand", "good", "household", "domain",
    "surname", "company", "pet", "baby", "business", "legal", "chinese",
}
DETERMINERS = {
    "the", "a", "an", "my", "your", "his", "her", "its", "their", "our", "this", "that",
    "same", "other", "one", "any", "no", "own", "such",
}
# words before "name" that make it a code identifier
CODE_WORDS = {
    "param", "parameter", "column", "function", "file", "variable", "field", "attribute",
    "key", "method", "class", "object", "property", "argument", "arg", "var", "dir",
    "directory", "table", "tool", "json",
}


def _word(s):
    s = s.strip().lower()
    return s if s.isalpha() else ""


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    word = _word(prev)

    value = 0.0
    if tok in NAME_WORDS:
        if word in NAMING_WORDS:
            value = -3.4
        elif word in DETERMINERS:
            value = -2.0
        elif word in CODE_WORDS:
            value = 0.0
        elif word:
            value = -1.0
        else:
            value = -0.6
    elif tok in NAMED_WORDS:
        value = -0.8
    elif tok in CAPS_NAME:
        value = -0.45
    elif tok in CODE_NAME:
        value = -0.26
    elif tok in ZH_NAME:
        value = -0.95
    elif tok == " with" and prev in START_WORDS:
        value = -1.2
    elif tok == " of" and prev in NAME_WORDS:
        value = 0.6
    return carry, value

programs.sol:
"""Approximate a code-header response, mainly Java imports and PHP uses.

Import/use after an unquoted semicolon-ended line is the main positive
cue; an earlier package keyword strengthens imports. Formatting changes
its amplitude. Literal escaped newlines and numbered listings are handled.
Most other positions are zero. Document starts have a weak negative bias
for words and punctuation, with positive exceptions for opening-brace
tokens without newlines and single uppercase Cyrillic letters. An isolated
initial bare import is negative. These rules leave many weak responses out.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    text, package = ('', False) if first else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if first and not token.startswith('<|'):
        if not word or all(unicodedata.category(c).startswith('P') for c in word):
            value = -0.25
        elif len(word) > 1:
            value = -0.14

    if word in ('import', 'use'):
        # Also read source code quoted inside strings, and numbered listings.
        normalized = re.sub(r'\\+[nr]', '\n', text)
        normalized = re.sub(r'\\+t', '\t', normalized)
        tail = re.sub(r'\s*(?:[0-9]+\s*)?$', '', normalized)
        line = tail.split('\n')[-1]
        header = tail.endswith(';') and not any(q in line for q in "\"'")
        escaped = bool(re.search(r'\\+n\s*$', text))
        value = -0.04 if word == 'import' else 0.0
        if word == 'import':
            if header:
                value = 1.55 if package else 0.97
                if escaped:
                    value = 1.1 if package else 0.87
                if token.startswith('\t'):
                    value = 0.58
                elif token.startswith(' '):
                    value = 0.92
            elif package and not any(q in line for q in "\"'"):
                value = 0.8
            if first and token == 'import':
                value = -0.87
        elif header:
            php = '\\' in tail or '<?php' in tail
            value = 1.25 if php else 0.23
            if token != 'use':
                value = 0.35 if php else 0.27
            if escaped:
                value = 0.3
        elif token == '\tuse':
            value = 0.2

    if first:
        if token.startswith('{') and '\n' not in token:
            value = 1.4
        elif (len(token) == 1 and token.isupper()
              and 'CYRILLIC' in unicodedata.name(token, '')):
            value = 0.68

    return (doc, (text + token)[-1024:], package or word == 'package'), value

programs.haiku:
"""Candidate 3: Java-style `import` lines, plus a rough rule for the first token of each row.

Activation is `import` opening a line right after a `;`-terminated line (a Java,
C# or PHP import block): about 1.4. Everywhere else it is near zero.
The first token of each packed row has no left context; its value depends on the
token itself. Rough rule: small function words (the, a, to, for, of, ...) lean
positive, punctuation and whitespace lean negative, other tokens sit in between.
"""

READS = ()

IMPORT_LEVEL = 1.4
FUNCTION_WORDS = {"the", "a", "an", "to", "for", "of", "in", "on", "with", "at", "from", "into", "all", "about", "and"}


def first_token_level(tok):
    word = tok.strip()
    if word in FUNCTION_WORDS:
        return 0.24
    if word == "" or all(not c.isalnum() for c in word):
        return -0.28
    if word.isdigit():
        return -0.04
    return -0.19


def step(carry, prefix, upstream):
    # carry: (last non-space character so far, whether the current line is still blank)
    last, blank = carry if carry is not None else (" ", True)
    tok = prefix.token_strings[-1]
    value = 0.0
    if prefix.position == 0:
        value = first_token_level(tok)
    elif blank and last == ";" and tok.strip() == "import":
        value = IMPORT_LEVEL
    for ch in tok:
        if ch == "\n":
            blank = True
        elif not ch.isspace():
            last, blank = ch, False
    return (last, blank), value

programs.sol:
"""Respond to isolated spaces in a document's extra-spacing style.

A space is usually weak, but becomes strong when earlier gaps contained
extra blanks. Distinguish spaces after words/numbers from indentation and
punctuation, and boost them when doubled standalone spaces occurred recently.
There are also explicit responses to a C include quote, traceback 'line',
and a document-initial 'Title:' header; other first tokens get a small offset.
These are coarse averages, not predictions of every lexical fluctuation.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
        spaces, extra_gaps, last_double = 0, 0, -100
    else:
        _, previous, position, spaces, extra_gaps, last_double = carry

    value = 0.0
    if position == 0:
        value = 0.19 if token == ' ' else -0.23
    elif token == ':' and previous == 'Title' and position == 1:
        value = 5.98
    elif token == ' "' and previous.strip() == '#include':
        value = 0.92
    elif token == ' line' and previous.endswith('\",'):
        value = 1.04
    elif token == ' ':
        fraction = extra_gaps / max(1, spaces)
        if previous.isspace():
            value = 0.045
        elif fraction <= 0.03:
            if previous.endswith(','):
                value = -0.07
            elif previous.endswith(':'):
                value = -0.13
            else:
                value = 0.02
        elif fraction <= 0.25:
            if previous.endswith('.'):
                value = 0.52
            else:
                value = 0.22 if previous.strip().isalnum() else 0.09
        elif previous.endswith('.'):
            value = 0.81
        elif previous.strip().isalnum():
            value = 1.0 if position - last_double <= 32 else 0.55
        else:
            value = 0.13

    # A completed extra gap may be two standalone blanks, or a standalone
    # blank followed by a word token that already has a leading blank.
    if previous == ' ' and token.startswith(' '):
        extra_gaps += 1
        if token == ' ':
            last_double = position
    if token == ' ':
        spaces += 1
    carry = (doc, token, position + 1, spaces, extra_gaps, last_double)
    return carry, value

"""Approximate a negative response to backward references.

The largest pulses are on this/these and multilingual demonstratives.
Preceding words distinguish demonstrative 'that', object 'it', and
substitute 'so' from their clause-linking or subject uses. Case, word
pieces, and source-code syntax matter too. This is a lexical/syntactic approximation, not coreference
resolution. Only a short text suffix is kept, resetting at document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

PREPOSITIONS = set('''
of for from with about without into onto upon by on to through after before
beyond against despite under over within in at during between
'''.split())
CLAUSE_LINKS = set('''
