'''.split())


@lru_cache(maxsize=4096)
def grammar(word):
    return (set(wordnet.base_forms(word)) | {word},
            'verb' in wordnet.parts_of_speech(word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()
    m = re.search(r'([^\W\d_]+|[^\w\s])\s*$', tail)
    prev = m.group(1).lower() if m else ''
    bases, verb = grammar(prev) if low in (
        'this', 'these', 'those', 'that', 'it', 'so') else (set(), False)
    spaced = token.startswith(' ')
    capital = bool(word and word[0].isupper())
    value = 0.0

    if low in ('this', 'these', 'those'):
        if not spaced:
            value = (-0.27 if low == 'this' else -0.8) if capital else 0.1
        elif capital:
            value = {'this': -0.68, 'these': -1.07, 'those': -0.48}[low]
        else:
            value = -1.25
            if prev in ('despite', 'without', 'beyond'):
                value = -4.7
            elif prev in ('upon', 'after'):
                value = -3.0
            elif prev == 'from':
                value = -2.7
            elif prev == 'of' or prev in ('all', 'both'):
                value = -2.0
            elif prev == 'like':
                value = -0.6
            elif prev in PREPOSITIONS:
                value = -1.75 if prev != 'in' else -1.35
            elif bases & {'be', 'think', 'love'} or prev in ('so', 'then'):
                value = -0.7
            elif bases & OBJECT_VERBS:
                value = -2.2
            elif prev in (',', '.'):
                value = -0.8
            if (low == 'this' and verb and
                    re.search(r'\bto\s+\w+\s*$', tail, re.I)):
                value -= 0.4
            if low == 'these':
                value -= 0.5
            elif low == 'those':
                value *= 0.5
        if re.search(r'\bbased (?:on|upon)\s*$|\bgiven\s*$', tail, re.I):
            value -= 1.4
        line = tail.rsplit('\n', 1)[-1]
        code = (re.search(r'\breturn\s*$|[{};=+]\s*$', tail) or
                (not line.strip() and len(line) >= 4) or
                token.startswith('\t'))
        if low == 'this' and code:
            value = 0.7
    elif low == 'that' and spaced:
        value = -0.89 if capital else -0.06
        if not capital:
            if prev in ('after', 'before'):
                value = -3.7
