        return -0.33
    if lower in POSSESSIVES:
        return -0.95
    if lower in DETERMINERS:
        if w[0].isupper():
            return -0.55
        return -0.01 if s.startswith(' ') else -0.38
    if lower in PREPOSITIONS:
        return 0.0
    if lower in CONJUNCTIONS:
        return -0.52
    if lower in ('of', 'as'):
        return -0.35
    if w.isdigit():
        return -0.27
    if regex.search(r'\p{Script=Han}', w):
        return -0.065
