    if s and set(s) == {'·'} and len(s) >= 2:
        return -1.73
    if s in ('辅', '輔'):
        return 7.7
    if '辅' in s or '輔' in s:
        return 2.7
    if s == '柔':
        return 4.5
    if '柔' in s:
        return 1.2
    if s == '友':
        return 1.3
