        return 3.22 if s.startswith('h') else 1.98

    if continuing and prev.endswith('ah'):
        return 2.44 if s[:1] and s[0] in 'lnr' else 0.16
    if before == 'e':
        if not s.endswith('h'):
            return 0.046
        if len(s) > 2:
            return -0.48
        return -0.37 if spelling_now.isupper() else -1.76
    return 0.004

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    if 'h' in spelling(text).lower() or spelling(prev).lower().endswith('h'):
        value = response(text, prev)
    else:
        value = 0.0
    return (doc, text), value

"""A token-boundary-sensitive, mostly negative response to the letter t.

Normalize t counterparts in Cyrillic, Greek and Arabic. Isolated T gets a
strong negative value; lowercase t is weaker inside an existing word. Give
alphabetic continuations of an isolated t a smaller negative response. For
other short t-initial pieces, use English frequency and word boundaries.
Literal backslash-t escapes are much stronger, especially after a piece
containing t. This approximation omits word-specific positive exceptions.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
T_EQUIVALENTS = str.maketrans({
    'Т': 'T', 'т': 't', 'Τ': 'T', 'τ': 't', 'ت': 't', 'ط': 't',
})


@lru_cache(maxsize=32768)
def letters(token):
    return ''.join(c for c in token.translate(T_EQUIVALENTS) if c.isalpha())


@lru_cache(maxsize=16384)
def frequency(word):
    return zipf_frequency(word, 'en')


def response(token, previous):
    word = letters(token)
    low = word.lower()
    before = letters(previous)
    before_low = before.lower()
    if token.startswith('\\t'):
        return -4.97 if 't' in before_low else -1.78
    if low == 't':
        if word[0].isupper():
            return -0.81
        if token[:1].isspace():
            return -0.70
        if 't' in before_low:
            return -1.01
        return -0.11 if before else -0.61
    if before_low == 't':
        if not token.isalpha():
            return -0.018
        return -0.64 if 't' in low else -0.26
    if not low.startswith('t'):
        return -0.007 if 't' in low else 0.006
    freq = frequency(low)
    if not freq:
        return -0.007
    if freq > 4.25:
        return 0.004 if low == 'the' else -0.036
    if len(word) > 2:
        return -0.31 if low.endswith('t') else -0.039
    if not token.isalpha():
        return -0.39
    if before:
        return 0.001
    return -0.71 if freq <= 3.75 else -0.26


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(token, previous)

