"""Whole-word detector for "crank" and its look-alike words.

The component is lexical: it reads the word the newest token belongs to, up to and
including that token, and looks it up in a short list of words. The value sits on the
token that completes the word. It is strongly positive for "crank" and its forms
(cranks, cranked, crankshaft), "prank", "crick", "crux", "planck" and "quark"; positive
for "shaft", "axle", "axial", "coaxial", "trunk" and "ankle"; and negative for "quart",
"pint", "quint" and a set of words with an -int, -ant or -ist sound (extant, squint,
pious). Words not in the list predict 0. A row's first token has no earlier text, and
predicts a small negative value on average. The list holds the strongest words only;
most of the component's variance comes from many weaker words this does not cover.
"""

READS: tuple[str, ...] = ()

# "crank" and words that look like it (cr-, pr-, k- and x- spellings).
CRANK = {
    "crank": 6.3, "cranks": 8.4, "cranked": 7.9, "cranking": 7.4, "cranky": 3.1,
    "crankshaft": 3.2, "crick": 2.5, "crux": 4.8, "cranial": 1.9, "intracranial": 2.2,
    "extracranial": 2.9, "transcranial": 2.3, "krank": 1.6, "cracks": 1.3,
    "prank": 4.3, "pranks": 8.0, "prak": 2.8,
    "planck": 3.5, "brux": 3.6, "knx": 3.2, "xknx": 3.2, "cetux": 2.3, "tranh": 3.2,
}

# Shaft, axle and trunk words.
SHAFT = {
    "shaft": 2.2, "axle": 3.2, "axles": 2.6, "axial": 2.2, "axially": 1.4,
    "coaxial": 3.3, "coaxially": 2.0, "uniaxial": 1.7, "coax": 1.5,
    "trunk": 2.8, "trunks": 3.0, "ankle": 1.6, "praxis": 2.4,
}

# Quark, a few related spellings.
QUARK = {"quark": 2.3, "quarks": 1.5}

# quart, pint and quint: negative.
VOLUME = {"quart": -1.4, "quint": -1.5, "pint": -1.6, "pints": -2.8, "interquart": -1.9}

# Words with an -int, -ant or -ist sound: negative.
INT_ANT = {
    "peint": -2.8, "cint": -4.0, "cist": -2.3, "scint": -2.6, "extant": -2.5,
    "squint": -2.7, "lecith": -2.1, "pious": -1.7, "pageant": -2.4, "decant": -2.1,
    "enceinte": -2.5, "acquist": -2.1, "cuant": -2.4, "conscientious": -1.7,
}

# Other words built from the same letters, in other languages and scripts.
OTHER = {
    "контрак": 4.9, "крут": 2.4, "конкурент": 2.1, "транс": 2.1, "perak": 2.2,
    "perox": 2.1, "prus": 3.3, "octah": 1.5, "tetrah": 1.6, "percutaneous": 1.6,
    "pancake": 1.5,
}

WORDS = {**CRANK, **SHAFT, **QUARK, **VOLUME, **INT_ANT, **OTHER}
ROW_START = -0.17  # mean activation of a row's first token


def current_word(prefix):
    """Letters of the word ending at the newest token, lowercased."""
    word = ""
    for raw in reversed(prefix.token_bytes):
        text = raw.decode("utf-8", "replace")
        if text[:1].isspace():
            return (text.strip() + word).lower()
        if not text.isalpha():
            break
        word = text + word
    return word.lower()


def step(carry, prefix, upstream):
    """The table value of the word the newest token completes, else the row-start value
    for a row's first token, else 0."""
    value = WORDS.get(current_word(prefix))
    if value is None:
        value = ROW_START if prefix.position == 0 else 0.0
    return carry, value

programs.sol:
"""A negative pulse on a document's first token, sustained while it repeats.

The pulse size depends on familiar surface classes of its initial token.
After the first different token, output zero. Document boundaries restart it.
This intentionally leaves out individual vocabulary items' idiosyncrasies.
"""
READS = ()

DECLARATIONS = frozenset('''
package import export def class int string bool char float double void
var const let function
'''.split())


def opening_value(text):
    token = text.strip()
    if text.startswith('<|'):
        return -44.1
    if not token:
        if '\t' in text:
            return -33.2
        if '\n' in text or '\r' in text:
            return -19.0
        return -10.6 if len(text) == 1 else -26.2
    if token.isdecimal():
        return -16.5
    if not any(ch.isalnum() for ch in token):
        if '\\' in token and len(token) > 1:
            return -32.4
        if len(token) > 1 and len(set(token)) == 1:
            return -31.3
        if text.startswith(' '):
            return -19.7
        if len(token) == 1 and token in '.,:;!?':
            return -15.6
        return -24.5
    if not token.isascii():
        return -33.8
    if token.isalpha():
        if text[0].isspace():
            return -29.3
        if token in DECLARATIONS:
            return -55.4
        return -39.6 if token[0].isupper() else -35.8
    return -34.2


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    first = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        value = opening_value(prefix.token_strings[-1])
        return (token, value), value
    if carry is not None and token == carry[0]:
        return carry, carry[1]
    return None, 0.0

"""An alternative/separator detector: 'or' and slashes, strongest in prose.

Keep 160 characters of left context. Downweight paths, units, formulas and
code; upweight joins after familiar English words or non-Latin letter runs.
Recognize related list, fraction and alternative markers too.
Reset context between documents.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
OR_WORDS = set('oder oppure или либо lub albo veya eller vagy sau atau '
               '或者 或 または 又は あるいは'.split())
UNITS = set('g kg mg ug lb lbs oz t st m cm mm km ft yd l ml dl cl '
            's ms min h hr mol mmol kPa um rad deg btu units byte kb mb gb tb'.split())
DIRECTORIES = set('src test tests lib bin usr tmp etc include home dev proc '
                  'sys root var opt dist build vendor pkg internal examples '
                  'public assets packages components modules scripts docs cmd tools '
                  'crates'.split())
# Slash variants, list separators, a parenthesis, and fraction notation.
# 之 appears in Chinese fractions (分之), as well as possessive constructions.
MARKERS = {'／': 1.4, '∕': 1.4, '⁄': 1.4, '・': 0.8, '、': 0.2,
           '（': 0.3, '}{': 0.65, '之': 0.8, ' ||': 0.25}


@lru_cache(maxsize=10000)
def familiar_word(word):
    return zipf_frequency(word.lower(), 'en') >= 3


def slash_join(token, recent):
    bare, space = token.strip() == '/', token.startswith(' ')
    chunk = re.split(r'\s|\\n|\\t', recent)[-1]
    line = re.split(r'\n|\\n', recent)[-1]
    match = re.search(r'\p{L}+\Z', recent)
    word = match.group() if match else ''
    path = (re.search(r'[._@`"\'\\]', chunk) or chunk.startswith('/') or
            any(p.lower().strip('([{<') in DIRECTORIES for p in chunk.split('/')) or
            ('-' in chunk and not all(p.isupper() or familiar_word(p)
                                      for p in chunk.split('-'))))
    path = path or re.search(r'\w+:\w+', chunk)
    if path:
        return 1.7 if space else 1.25 if bare else 0.08
    formula = re.search(r'[=^∂∫]|\\(?:frac|sum|cdot)', line[-60:])
    code = re.search(
        r'^\s*(?:import|#include|from|test|pytest|python|cd|cat|modified|deleted)\b',
        line)
    code = code or re.search(r'^\s+at\s+|(?:PASSED|FAILED)\b', line)
    if not code and recent.count('/') >= 2 and 'http' not in recent:
        code = re.search(r'\.\w{1,5}\b', recent)
    mime = word.lower() in ('text', 'application', 'multipart', 'message', 'font')
    unit = word.lower().replace('µ', 'u').replace('μ', 'u') in UNITS
    if formula or code or mime or unit:
        return (1.2 if formula else 1.6) if bare else 0.3
    if not word:
        return 1.65 if space else 1.5 if bare else 0.3
    if word.lower() in ('he', 'she', 'him', 'her', 'his'):
        value = 4.0
    elif (not word.isascii() and
          not re.match(r'\p{Script=Greek}', word)):
        value = 2.4 if space else 3.4
    elif word.isupper():
        value = 2.2
    elif len(word) >= 3 and familiar_word(word):
        value = 2.4 if space else 3.6
    elif len(word) <= 2:
        value = 1.3 if bare else 0.95
    else:
        value = 2.1 if bare else 1.3
    return value / (1 + 0.25 * chunk.count('/'))


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    s = token.strip()
    value = MARKERS.get(token, 0.003)
    if s.lower() == 'or':
        value = 0.32 if s == 'Or' else 0.55 if token.startswith(' ') else 0.09
    elif s.lower() in OR_WORDS:
        value = 0.7
    elif token == ' ou':
        value = 1.0
    if '/' in token:
        if s == '/' and '\n' in token:
            value = 0.8
        elif s == '/or' and re.search(r'\band\Z', recent.lower()):
            value = 3.1
        elif s == '/' or re.fullmatch(r'/[A-Za-z]+', s):
            value = slash_join(token, recent)
        elif '://' in s:
            value = 1.5
        elif s.startswith('</') or s.startswith('></'):
            value = 0.15
        elif s.startswith('//'):
            value = 0.3 if s.startswith('///') else 0.1
        elif s.startswith('/*'):
            value = 0.8 if s.startswith('/**') else 0.37
        elif s.startswith('*/'):
            value = 0.03
        else:
            value = 0.8
    return (doc, (recent + token)[-160:]), value

"""Approximate a sparse mixture of typography, lexical cues and document starts.

Unicode separators usually give negative pulses, weakened on repetition.
There are smaller lexical responses to English degree/negation expressions
and Chinese negation and boat morphemes. Initial tokens are a separate case:
capitals and heading markers tend positive; the '2' of an initial '12' dips
strongly. Split UTF-8 symbol bytes get additional negative responses.
Repeated-mark attenuation follows the weakening seen in training examples.
This captures only part of the component's context dependence.
"""
import unicodedata

READS = ()
# Character: (steady response, extra response on its first appearance).
SEPARATORS = {
    '‐': (0.06, -1.76),        # Unicode hyphen, not ASCII '-'
    '\u00ad': (-0.25, -0.36), # soft hyphen
    '…': (-0.05, -0.15),
    '・': (-0.01, -0.29),      # Japanese middle dot
