def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', {}, '', b'')
    _, position, history, counts, first, tail = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    raw = prefix.token_bytes[-1]
    value = 0.0

    for ch, (steady, novel) in SEPARATORS.items():
        if ch in text:
            value += steady + novel / (1 + counts.get(ch, 0))
    box = any('BOX DRAWINGS' in unicodedata.name(ch, '') for ch in text)
    if box:
        value -= 0.52 / (1 + counts.get('box', 0))
    if '…' in text and '\n' in text:
        value -= 0.09
    if '·' in text:
        value += -0.63 if text.count('·') >= 2 else 0.10
    if '～' in text:
        value -= 0.24 / (1 + counts.get('～', 0))
    if '–' in text:
        value += -0.04 if text.startswith(' ') else 0.11
    if '≠' in text:
        value -= 0.33
    if '∂' in text or word == 'partial':
        value += 0.21
    if word == '``':
        value -= 0.05 + (0.21 if '\xa0' in history else 0)
    if '\xa0' in text:
        value += 0.04

    if raw and all(0x80 <= b < 0xc0 for b in raw):
        value -= 0.01
        ch = (tail + raw).decode('utf8', 'replace')[-1:]
        if ch and unicodedata.category(ch)[0] in ('P', 'S', 'Z'):
            value -= 0.07
