        if tail.endswith((b'\xe2', b'\xef')):
            value -= 0.54

    if word == 'very':
        value += 0.17
    if word == 'without':
        value -= 0.10
    if word == 'quite' and history.lower().rstrip().endswith(
        ('not', "n't", 'n’t', 'never')
    ):
        value -= 0.56
    if word == 'pages' and history.rstrip().endswith('preview shows'):
        value += 0.90
    if word.startswith('不'):
        value += 0.06 + (0.13 if word == '不是' else 0)
    if '船' in word:
        value -= 0.96 / (1 + counts.get('船', 0)) ** 0.5

    if position == 0:
        value += 0.19 if word and word[0].isupper() else 0
        value -= 0.06 if text.startswith(' ') else 0
        value += 0.55 if text.startswith('#') else 0
        value += 0.33 if text.startswith('\n') else 0
