"""A sparse response to URL separators, TeX control words, and math typography.

Large observed responses cluster around URLs and mathematical notation; the
small, varied background is left at zero. TeX entries name the word read so
far: e.g. 'phant' is the first token of \\phantom. Separate pieces of a
control word can have different responses. The short text/byte tails reset
at document boundaries and let split control words and Unicode work.
"""
import re
import unicodedata

READS = ()

# Names read after a backslash (including unfinished multi-token names).
TEX = {
    # Delimiters, relations, and marks.
    'Vert': -3.3, 'vert': -4.5, 'langle': -2.3, 'lbrace': -2.8,
    'mid': -2.4, 'colon': -3.6, 'ast': -2.5,
    'dagger': -1.15, 'prime': -1.0, 'dots': -0.85,
    'rightarrow': -0.65, 'to': -0.7, 've': -1.4, 'vee': -0.7,
    # Large operators and accents.
    'lim': 2.0, 'sum': 1.55, 'prod': 2.6, 'pro': 2.9,
    'propto': 1.9, 'dot': 1.5, 'hbar': 1.85,
    'over': -0.45, 'overline': 0.5, 'overrightarrow': 0.65,
    # Layout, labels, and text formatting.
    'phant': -2.45, 'phantom': -0.35, 'hs': -1.5,
    'cr': -3.55, 'operator': -0.95, 'operatorname': 0.2,
    'begin': -0.55, 'label': -0.5, 'rm': -0.5,
    'mbox': 1.1, 'hbox': 1.5, 'quad': -0.65, 'qquad': -0.5,
    'overs': -1.65, 'overset': -0.7, 'unders': -1.3,
    'underset': -1.25, 'mathop': -1.4, 'ce': -0.9,
}
COMMAND = re.compile(r'\\([A-Za-z]+)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, byte_tail = '', b''
    else:
        _, tail, byte_tail = carry
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    value = 0.0

    if s == '://':
        scheme = tail.rsplit(maxsplit=1)[-1] if tail.strip() else ''
        if scheme.endswith('https'):
            value = 1.4
        elif scheme.endswith('http'):
            value = 1.6
        else:
            value = 0.3
        if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == doc:
            prev = prefix.token_strings[-2]
            if prev.startswith(' ') and prev.strip() in ('http', 'https'):
                value += 0.12
