            elif ch in '⟨〈':
                value = -1.25
            elif ch == '＜':
                value = -0.95
            elif ch == '‑':
                value = -1.8
            elif ch in '∛∝':
                value = 2.5
            elif s and all(c == '·' for c in s):
                value = -0.24 * len(s)

    return (doc, (tail + s)[-64:], (byte_tail + b)[-5:]), value

