            elif old_line == "Background":
                value = 1.9 if match[1] == "Background" else 0.55
            elif heading == "INTRODUCTION":
                value = 1.0 if old_line == "INTRODUCTION" else 0.35
            elif heading in {"RESULTS", "CONCLUSION", "Conclusion"}:
                value = 0.6
            elif heading == "CONCLUSIONS":
                value = 0.3
            elif (token == "\n" and match[1] == old_line
                  and old_line.isdigit() and len(old_line) <= 3):
                value = 0.7
            elif line.startswith("```"):
                value = 1.8
        elif line == "Introduction":
            value = 3.75
        elif line == "Background" and match[1] + token == "Background":
            value = 2.0
        elif heading == "INTRODUCTION":
            value = 2.1 if line.startswith("I.") else 3.1
        elif heading in {"CONCLUSION", "CONCLUSIONS"}:
            value = 2.1
        elif line in {"``", "```"}:
            value = 2.5

    # Stock controls and captions in scraped web pages.
    if token == " Tags" and before.endswith(("Show", "Hide")):
        value = 2.7 if "[#permalink]" in before else 0.95
    elif token == " pages" and before.endswith("This preview shows"):
        value = 7.2
    elif token == " page" and before.endswith("This preview shows"):
        value = 3.0
    elif token == " pages" and before.endswith("This preview shows document"):
        value = 1.9
    elif token == " navigation" and before.endswith("Toggle"):
        value = 7.5
    elif token == " languages" and before.endswith("Suggested"):
        value = 8.5
    elif token == " verified" and before.endswith("Expert"):
        value = 8.5
    elif token == ":" and before.endswith(("\n\nSubject", "# Thread")):
        value = -1.15
    elif token == " sites" and before.endswith("Share on other"):
        value = 1.2
    elif token == " Categories" and before.endswith("Browse by"):
        value = 0.8
    elif token == " links" and before.endswith("External"):
        value = 0.65
    elif token == " languages" and before.endswith("Show all"):
        value = 1.6
    elif token == " commands" and before.endswith("user"):
        value = 1.4
    elif token == "php" and before.endswith("<?"):
        value = -1.1 if before in {"<?", "\r\n<?"} else -0.25

    return (doc, text[-192:]), value

"""Lexical scope/location markers with a short preceding-language heuristic.

The largest response is to a URL's scheme separator. Smaller positive
responses include Romance 'of the' forms and articles after 'de', elided
articles, and several languages' 'in'. Spellings such as 'do', 'a', and 'v'
need language context: recent words vote by their corpus frequencies.
A few source-code scope markers are separate cases. Matches can also be
word-initial fragments, since the rest of the word is not yet visible.
Most tokens stay near zero; their small lexical variations are not modeled.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'pl', 'cs', 'sk', 'hu', 'nl')
# Default readings of ambiguous word forms; language-specific readings below.
FORMS = {
    'du': .25, 'des': .35, 'del': .65, 'do': -.05, 'dos': -.10,
    'da': -.02, 'das': -.02, 'em': 0., 'in': .035, 'im': 0.,
    'en': -.05, 'a': 0., 'az': -.02, 'v': .02, 'w': .02,
}
LANGUAGE_FORMS = {
    'de': {'in': .56, 'im': .70, 'du': -.03, 'des': -.06, 'v': .15},
    'fr': {'en': -.20, 'du': 1.15, 'des': .83},
    'es': {'en': .70, 'del': 1.07, 'a': -.13},
    'it': {'in': .14, 'del': 1.28, 'a': -.13},
    'pt': {'do': 1.24, 'dos': 1.42, 'da': 1., 'das': 1.,
           'em': .72, 'a': .09},
    'hu': {'a': .74, 'az': .75},
    'cs': {'v': .65}, 'sk': {'v': .65}, 'pl': {'w': 1.0},
}
ARTICLES = {'le': .11, 'les': .15, 'los': .23, 'las': .11,
            'il': .20, 'gli': .31, 'os': .16}

@lru_cache(maxsize=30000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language(text):
    # Single-letter variables are not useful evidence about the language.
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower())
             if len(w) > 1][-16:]
    scores = [0.] * len(LANGUAGES)
    for word in words:
        for i, frequency in enumerate(frequencies(word)):
            scores[i] += frequency
    best = max(range(len(scores)), key=scores.__getitem__)
    if scores[best] - scores[0] < 2.0:
        return 'en'
    return LANGUAGES[best]


def value_for(token, previous, context):
    word = token.strip().lower()
    if token == '://':
        return 2.10
    if word == 'namespace':
        line_start = not context.rsplit('\n', 1)[-1].strip()
        return 1.23 if line_start else .40
    if token == '_modules' and context.endswith('node'):
        return .48
    if word == 'once' and previous.strip() == '#pragma':
        return .75
    if token == ':' and previous.strip().lower() == 'doi':
        return .70
    boundary = token[:1].isspace() or not previous[-1:].isalpha()
    if not boundary:
        stem = previous.strip().lower()
        if token in {"'", '’'}:
            if stem in {'l', 'dell'}:
                return .70 if previous.strip() != 'L' else .35
            if stem == 'd':
                return .32
        if word in {"'un", '’un', "'une", '’une'} and stem == 'd':
            return .95
        return -.003
    if word == 'в':
        return .60
    if previous.strip().lower() == 'de':
        if word in {'la', 'los'}:
            return 1.08
        if word == 'l':
            return 1.18
        if word == 'las':
            return .74
    if word in {'della', 'delle', 'dei', 'degli', 'dello'}:
        return 1.10
    if word == 'dell':
        return 1.25
    if word in FORMS:
        if word == 'in' and not context:
            return .425
        readings = LANGUAGE_FORMS.get(language(context), {})
        return readings.get(word, FORMS[word])
    if word in ARTICLES:
        return ARTICLES[word]
    if word in {'zum', 'vom', 'beim', 'dal', 'dai', 'dalle'}:
        return .53
    if word in {'au', 'aux', 'dalla', 'zur'}:
        return .23
    if word == 'dans':
        return -.25
    if word in {'di', 'à', 'para'}:
        return -.14
    if word in {'at', 'on', 'for', 'into', 'de'}:
        return -.04
    return -.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, context = '', ''
    else:
        _, previous, context = carry
    token = prefix.token_strings[-1]
    value = value_for(token, previous, context)
    return (doc, token, (context + token)[-220:]), value

programs.haiku:
"""Layer-1 MLP down_proj, component 2553 of Qwen3-1.7B: a "foreign function word" detector.

What it responds to (read off its activations on training text):
- the "://" of a URL: the strongest response, about 2;
- "of the" / "from the" written as one word in Romance and German: del, della, dell,
  delle, dei, degli, dello, des, du, dos, dal, da (about 0.9);
- the article right after "de" in French/Spanish/Portuguese text ("de la", "de l'"),
  about 1;
- "in" and similar prepositions in other languages: Russian в, Spanish/Portuguese en,
  Portuguese em and do, German im, vom, zum, Polish w (about 0.5);
- other foreign articles and elisions (la, le, les, los, las, il, l', 'un, 'une) (about 0.2).

These foreign words count in full when the recent text is not English, and at one fifth
of that when it is. "Recent text" is the last 32 tokens of the same document, and
English means containing few English stopwords (the, and, of, to, is, ...). Every other
token, including English "in", "of" and "the", gives 0.

Main program: `step` looks up the token just written (and the one before it), and sets
the value from the classes above. It is a token-level rule: it does not model why the
component fires on these words, and it misses the spread of smaller responses.
"""

READS = ()

URL_SEP = {"://"}
OF_THE_CONTRACTED = {" del", " della", " dell", " delle", " dei", " degli", " dello",
                     " des", " du", " dos", " dal", " da", " Del", " Dell", " DU", " Dos"}
IN_WORDS = {" в", " В", "В", " en", " em", " im", " w", " vom", " zum", " do"}
ARTICLES = {" la", " le", " les", " l", " lo", " los", " las", " il", "'", "’", "'un", "'une"}
ENGLISH_WORDS = {" the", " and", " of", " to", " is", " that", " with", " for", " this",
                 " are", " be", " it", " was", " as", " by", " from", " which", " have",
                 " an", " or", " not", " you", " your", " in", " on", " at"}


def english_share(prefix):
    """Share of English stopwords among the last 32 tokens of the same document."""
    doc = prefix.document_ids[-1]
    seen = 0
    english = 0
    for i in range(len(prefix.token_strings) - 1, max(-1, len(prefix.token_strings) - 33), -1):
        if prefix.document_ids[i] != doc:
            break
        seen += 1
        english += prefix.token_strings[i] in ENGLISH_WORDS
    return english / max(seen, 1)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in URL_SEP:
        return None, 2.0
    if tok in OF_THE_CONTRACTED:
        return None, 0.9
    if prev == " de" and tok in ARTICLES:
        return None, 1.0
    if tok in IN_WORDS or tok in ARTICLES:
        base = 0.5 if tok in IN_WORDS else 0.2
        gate = 1.0 if english_share(prefix) < 0.05 else 0.2
        return None, base * gate
    return None, 0.0

programs.sol:
"""Approximate a few conspicuous continuation patterns.

Give 'more' a large positive value after 'no' or 'any'.
There are also spelling-sensitive rules at token boundaries: short
e-ending fragments, the digraph 'ye', and repeated middle-dot filler.
Unmodeled positions are assigned zero, not individual token lookup values.
All context is restricted to the current document.
"""
import re

READS = ()


def predict(token, previous):
    word = token.strip().lower()
    before = previous.strip().lower()
    if token[:1].isspace():
        if word == 'more':
            if before in {'no', 'any'}:
                return 5.4
            if before == 'some':
                return 1.9
            if before == 'not':
                return 0.6
            return -0.13
        if word == 'longer':
            if before == 'any':
                return 3.5
            if before == 'no':
                return 0.5
            return -0.15
        if word == 'further' and before in {'no', 'any'}:
            return 0.7
        if word == 'mere':
            return 1.0
        if word == 'anymore':
            return 1.8

    # These rules concern a fragment inside an alphabetic word.
    s = token.lower()
    if previous[-1:].isalpha() and s.isascii() and s.isalpha():
        if s in {'ye', 'yer', 'yes', 'yers'}:
            return -2.1 if before[-1:] in 'aeiou' else -0.23
        if before.endswith('y') and s in {'e', 'es'}:
            return -1.0
        if (before.endswith('y')
                and re.fullmatch(r'[b-df-hj-np-tv-z].{0,2}es?', s)):
            # y-te and y-the endings get the strongest spelling response.
            if re.fullmatch(r'th?es?', s):
                return 2.5
            if re.fullmatch(r'[bcdfghjklmnpqrstvwxyz]{1,2}es?', s):
                return 1.2
            return 0.1
        if before.endswith('t') and s in {'re', 'res'}:
            return 0.3
        if (re.fullmatch(r'[bcdfghjklmnpqrstvwxyz]{1,2}', before)
                and before[-1:] in 'mnpt'
                and re.fullmatch(r'[aeiouy]+[rltk]es?', s)):
            return 0.65
    if token == previous == '··':
        return 0.73
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, predict(prefix.token_strings[-1], previous)

"""Estimate a short-lived document-start response from token shape.

Opening punctuation, quotes, tab indentation, escaped controls, and high
single digits receive positive estimates. Closing brackets and ordinary
words receive negative estimates. Keep this estimate while the initial
token repeats; otherwise predict zero, except at the colon in an opening
'Title:' field. This coarse boundary model omits word-specific responses.
"""

READS = ()


def opening_value(s):
    t = s.strip()
    if t.startswith('<|'):
        return 0.0
    if not t:
        if s == '\r':
            return 3.5
        if s and set(s) == {'\t'}:
            return 2.05 / len(s)
        return 0.5 if '\t' in s else 0.0
    if len(t) == 1 and t in '0123456789':
        n = int(t)
        return 0.49 if n == 0 else -0.15 + 0.017 * max(0, n - 4) ** 3
    if t.startswith(('\\n', '\\t', '\\r')):
        return 2.6
    if not any(c.isalpha() for c in t):
        if set(t) == {'·'}:
            return 3.23
        if any(c in '\'"“”‘’«»' for c in t):
            if t == '"' and not s.startswith(' '):
                return 3.7
            return 1.7 if t == "'" else 2.2
        if set(t) == {'*'}:
            return 2.9
        if all(c in '({[' for c in t):
            return 3.0 if t == '{' and '\n' not in s else 0.8
        if all(c in ')}]' for c in t):
            return -1.6 if t == '}' else -0.4
        if t in ('.', '。'):
            return 2.0 if s.count('\n') == 1 else 0.5
        return 0.25
    return -0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token, True, text, 1), opening_value(text)
    _, first, repeated, first_text, count = carry
    repeated = repeated and token == first
    value = opening_value(text) if repeated else 0.0
    if count == 1 and first_text == 'Title' and text == ':':
        value = -5.32
    return (doc, first, repeated, first_text, count + 1), value

