"""Candidate v2: v1 plus a 'Title:' template rule."""
import re

READS = ()

WORD = re.compile(r" ?[A-Za-z]{2,}")
DOT = "··"  # the token "··"


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    t = prefix.position
    starts = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts:
        if WORD.fullmatch(cur):
            return None, -0.3
        if cur[:1].isdigit():
            return None, 0.1
        if cur[:1] == " " and cur[1:2] and not cur[1:2].isalnum():
            return None, 0.8
        if cur[:1] and not cur[:1].isalnum() and cur[:1] != " ":
            return None, 0.3
        return None, -0.2
    if cur == DOT and toks[-2] == DOT:
        return None, 3.2
    if t == 1 and cur == ":" and toks[0] == "Title":
        return None, -5.3
    return None, 0.0

programs.sol:
"""Sparse spelling rules centred on Chinese 要 (want/need).

Only-if, prohibition, and wanting phrases have the strongest negative
values; necessity/importance compounds and longer merged tokens are weaker.
Words beginning 要 are muted immediately after Chinese sentence boundaries.
Smaller rules cover yao/yo spellings, 摘 (pick/abstract), and vowel fragments
following y. These are observed spelling preferences, not a pure semantic
necessity detector. Unmatched tokens get zero, omitting the background.
Carry preserves unfinished UTF-8 and the previous token, resetting by document.
"""
from functools import lru_cache
import codecs
import re
import unihan
from pypinyin import lazy_pinyin, Style

READS = ()

@lru_cache(maxsize=8192)
def lexical_value(text):
    if text.startswith('只需'):
        return -2.3
    if '要' in text:
        i = text.index('要')
        before, after = text[:i], text[i+1:]
        weights = {'只': -6.2, '不': -4.4, '想': -4.1, '我': -4.3,
                   '你': -4.3, '既': -4.3, '主': -3.0, '首': -2.8,
                   '必': -2.1, '需': -1.0, '重': -1.4, '都': -2.7,
                   '就': -2.8, '是': -2.7, '还': -1.6, '還': -1.6}
        value = weights.get(before[-1:] or '', -2.1)
        if len(before) > 1:
            value *= 0.68
        if after:
            value *= 0.85 if before.endswith('只') else 0.4
        if text == '要是':
            value = -1.6
        return value
    if len(text) == 1 and lazy_pinyin(text, style=Style.TONE3) == ['yao2']:
        meaning = unihan.definition(text) or ''
        if 'shake' in meaning:
            return -5.3
        if 'rumor' in meaning:
            return -0.2
        if 'distant' in meaning:
            return -1.1
        return -3.8
    if text in ('曜', '揺'):
        return -5.3
    if text in ('摘', '摘要'):
        return -1.4 if text == '摘' else -2.9
    if text.strip() == '요':
        return -4.1
    word = text.strip().lower()
    if word == 'yao':
        return -6.3
    if word == 'yak':
        return -3.6
    if word in ('yam', 'yok'):
        return -1.3
    if text.strip() == 'YO':
        return -2.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '')
    _, pending, previous = carry
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    text = decoder.decode(pending + prefix.token_bytes[-1], final=False)
    pending = decoder.getstate()[0]
    value = lexical_value(text)
    lower = text.lower()
    # These continuations complete y-initial syllables across a token boundary.
    if previous.lower().endswith('y') and text and not text[0].isspace():
        if re.fullmatch(r'[aou]k|[aou]k[aiou]|uck', lower):
            value = -3.3
        elif re.match(r'[aou]k', lower):
            value = -1.0
        elif re.match(r'[ao]sh', lower):
            value = -1.4
        elif lower.startswith(('ur', 'ux')) or lower in ('aw', 'ō', 'ù'):
            value = -1.9
    if lower == 'ao' and previous.strip().lower() in ('ch', 'sh'):
        value = -2.8
    if lower == 'ak' and previous.lower().endswith(('oi', 'owi', 'ili')):
        value = -1.7
    if text.startswith('要') and previous.rstrip().endswith(('。', '；')):
        value = 0.0
    if text == '要' and previous.endswith(('简', '簡')):
        value = -6.0
    if text == '必要' and previous.endswith(('务', '務')):
        value = -5.2
    if text == 'к' and previous.lower().endswith('я'):
        value = -2.8
    if text == 'や':
        value = -2.2 if previous.endswith(('よう', 'や')) else -0.2
    # An isolated continuation byte after a generic Han lead byte is
    # sometimes the first recognizable part of 摇's spelling.
    if pending == '摇'.encode('utf-8')[:2] and previous.strip() == '':
        value = -4.5
    return (doc, pending, text), value

programs.haiku:
"""Yao-sound tokens: the component is negative on Chinese words read yào/yáo (要 and its
compounds meaning "want", "will", "only if", "must", "main", "essential"), and on a few
other yao-sounding tokens (摇, 姚, 瑶, 曜, Yao, Korean 요).

It is most negative on the "want/only-if" compounds (只要, 不要, 想要, 我要), a little less
on the bare verb 要, and weakest on 需要 / 必要 / 重要 / 主要. A bare 要 that starts a
clause after a full stop or semicolon (an imperative "must ...") is slightly positive.
Everything else predicts 0, except the colon of a document that opens with "Title:".
"""

READS = ()

WANT_COMPOUNDS = {"只要", "不要", "想要", "我要", "你要", "是要", "非要", "就要", "都要",
                  "既要", "还要", "也要", "只要是", "也不要", "还是要", "就是要"}
ESSENTIAL = {"需要", "必要", "重要", "主要", "首要", "只需要", "不需要", "主要是", "要是"}
YAO_SOUND = {"摇", "姚", "瑶", "曜", "遥", "Yao", "요"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    after_eot = len(prefix) > 2 and prefix.token_strings[-3] == "<|endoftext|>"
    if token == ":" and before == "Title" and after_eot:
        return None, 4.6
    if token == "要":
        return None, (0.8 if before in ("。", "；") else -2.0)
    if token in WANT_COMPOUNDS:
        return None, -4.5
    if token in YAO_SOUND:
        return None, -4.5
    if token in ESSENTIAL:
        return None, -1.5
    return None, 0.0

programs.sol:
"""Approximate a signed type/code-expression response from local text.

Recognized capitalized type names and class stems are positive; lowercase
primitive types are negative. Declaration markers, casts, type annotations,
generics and `new` change their strength. Receiver/superclass keywords and a
few literals have separate syntax-sensitive responses. Words inside longer
identifiers are attenuated. Most other words produce zero, apart from a weak
capitalized-name response in type-like positions. URL separators and doubled
middle dots have fixed responses.

Only the last 256 characters are retained, reset at document boundaries.
This is a local heuristic, not a programming-language parser.
"""
import re

READS = ()
LOWER_TYPES = set('int uint char wchar byte sbyte short ushort long ulong '
                  'float double bool boolean void string object mixed var'.split())
UPPER_TYPES = set('String Int Integer UInt Uint Byte Short Long Float Double '
                  'Bool Boolean Char Void Object Class Default Static'.split())
MODIFIERS = set('public private protected final static readonly volatile '
                'abstract virtual override extern signed unsigned const'.split())
WORD = re.compile(r'[A-Za-z_]+$')
TYPED_CODE = re.compile(r'\b(public|private|protected|static|final|namespace|'
                        r'String|void|int)\b')
CODE = re.compile(r'[;{}]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    carry = (doc, (tail + token)[-256:])
    match = WORD.search(token)
    if not match:
        if token == '://':
            return carry, -0.38
        if token == '··':
            return carry, 1.1
        if token == '<':
            prev = WORD.search(tail)
            if prev and prev[0][0].isupper():
                return carry, 1.35
        return carry, 0.0
    word = match[0]
    lead = token[:match.start()]
    before = tail + lead
    trim = before.rstrip()
    previous = WORD.search(trim)
    prev = previous[0] if previous else ''
    line = before.split('\n')[-1]
    indent = bool(line) and not line.strip()
    continuation = not lead and tail and (tail[-1].isalpha() or tail[-1] == '_')
    typed = bool(TYPED_CODE.search(tail))
    code = bool(CODE.search(tail))
    initializer = line.strip() == ':' or bool(re.search(r'\)\s*:$', line.rstrip()))
    value = 0.0
    if word == 'this':
        if initializer and typed:
            value = -5.5
        elif indent:
            value = (-4.0 if trim.endswith('{') else -3.2) if typed else (
                -2.8 if '\t' in lead else -1.35)
        elif code:
            value = -1.7 if typed else -0.5
        else:
            value = 0.03 if lead.isspace() else -0.28
    elif word == 'super':
        if prev == 'return' and code:
            value = -4.8
        elif typed:
            value = -5.8 if trim.endswith('{') else -3.85
        else:
            value = -1.15 if code else 0.2
    elif word == 'base':
        value = -6.0 if initializer and typed else 0.0
    elif word in LOWER_TYPES or word in UPPER_TYPES:
        upper = word in UPPER_TYPES
        paren = trim.endswith(('(', '?'))
        angle = trim.endswith('<')
        colon = line.rstrip().endswith(':')
        modifier = prev in MODIFIERS
        new = prev == 'new'
        if upper:
            strength = 0.04 + 0.7 * typed + 0.8 * code
            strength += 0.25 * paren + 0.87 * angle + 0.26 * colon
            strength += 0.96 * modifier + 0.34 * new
        else:
            strength = 0.05 + 0.43 * typed + 0.42 * code
            strength += 0.6 * paren + 0.14 * angle + 0.77 * colon
            strength += -0.12 * modifier + 1.44 * new
        strength = max(0.0, strength)
        if continuation:
            strength *= 0.05
        root = word.lower()
        if root == 'string':
            gain = 0.6 if upper else 1.8
        elif root in ('int', 'integer', 'uint'):
            gain = 1.25 if upper else 0.92
        elif root in ('byte', 'sbyte'):
            gain = 0.85 if upper else 1.9
        elif root in ('char', 'wchar'):
            gain = 0.5 if upper else 1.1
        elif root in ('float', 'double', 'bool', 'boolean'):
            gain = 1.7 if upper else (
                0.7 if root in ('bool', 'boolean') else 1.1)
        elif root == 'void':
            gain = 1.9 if upper else 0.45
        elif root == 'object':
            gain = 0.12 if upper else 0.72
        elif root in ('var', 'mixed'):
            gain = 0.3
        elif word in ('Class', 'Default', 'Static'):
            gain = 1.7
        else:
            gain = 1.0
        value = (1 if upper else -1) * gain * strength
    elif word == 'null':
        operator = trim.endswith(('=', '!', '?', '|', '&'))
        value = -1.5 if operator else -0.55 if typed else -0.23 if code else 0.0
    elif word == 'NULL':
        value = 0.35
    elif word == 'None':
        value = -0.15
    elif word == 'break':
        if code:
            value = -1.15 if indent else -0.36 if lead.isspace() else -1.7
        else:
            value = 0.05
    elif word == 'self':
        value = -0.15
    elif word == 'value':
        value = -0.65 if typed else -0.25 if code else -0.15 if not lead else 0.0
    elif word[0].isupper() and not continuation:
        if trim.endswith('<'):
            value = 0.9 if typed else 0.5 if code else 0.1
        elif typed:
            value = 0.58 if prev in MODIFIERS else 0.05
    return carry, float(value)

"""A sparse detector of openings in structured text.

Negative pulses mark diff headers, record-field colons, shell commands, and
code and TeX declarations. PASS and URL-path openings give positive pulses.
These local format cues account for many observed activation spikes. Rules
use spelling and nearby syntax, not token IDs. Unrecognized text is zero.
A bounded text tail is cleared whenever the packed input changes document.
"""
import re

READS = ()

# Forum records, document headings, and mail headers.
FIELDS = {
    'Joined': -8.7, 'Posts': -2.9, 'Category': -2.5,
    'Content-Type': -4.0, 'Content-Transfer-Encoding': -5.6,
    'MIME-Version': -1.5, 'Message-ID': -1.6,
    'Subject': -1.8, 'Date': -0.8, 'Location': -1.8,
    'Status': -1.3, 'Concentration': -1.3, 'Kudos': -1.0,
    'Time': -0.8, 'Step': -0.6, 'PASS': -0.8, 'Re': -0.6,
    'Purpose': -2.8,
}
# Keys of a blog post's YAML front matter.
YAML_FIELDS = {
    'layout': -14.0, 'title': -4.6, 'date': -4.5,
    'tags': -4.0, 'categories': -4.0, 'category': -5.5,
    'author': -4.0, 'permalink': -7.0, 'published': -5.0,
    'status': -4.5, 'draft': -4.5, 'path': -3.0,
    'tagline': -3.0, 'display_name': -5.0,
}
MODIFIER = re.compile(r'\b(public|private|protected|static|final|default)\s*$')


def response(token, before):
    word = token.strip()
    # Literal escaped newlines occur inside tool-call JSON strings.
    text = before.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    start = not line.strip() or re.fullmatch(r'\s*\d+\s*', line)

    if word == '+++' and start:
        return -12.1
    if word in {'a', 'b'} and line.strip() == ('---' if word == 'a' else '+++'):
        return -3.5 if word == 'a' else -4.6
    if word == '---' and start and '\n' not in token:
        return -1.7
    if word == 'PASS' and line.rstrip().endswith('---'):
        return 1.6

    if word == 'index' and start and 'diff --git' in text:
        return -1.0
    if word == 'git' and text.rstrip().endswith('diff --'):
        return -0.7
    if token == '/' and re.search(r'https?://[^/\s"<>]*$', text):
        return 0.8

    if token == ':':
        match = re.search(r'([\w-]+)$', text)
        label = match[1] if match else ''
        if label == 'Title' and text == 'Title':
            return -9.5
        if re.search(r'(?m)^---\s*$|\nlayout:', text):
            return YAML_FIELDS.get(label, -0.15)
        if label in {'modified', 'deleted'}:
            return -1.3 if label == 'modified' else -2.1
        if label in FIELDS:
            return FIELDS[label]
        if re.fullmatch(r'\s*[A-Z][a-z]+', line):
            return -0.2
        return -0.03

    if word == 'cd':
        if token.startswith(' ') and (start or text.rstrip().endswith(('&&', ';'))):
            return -5.0
        if before.endswith('"'):
            return -3.5
        if start or before.endswith('`'):
            return -2.8
        return 0.0
    if word == 'cat':
        if before.endswith('`'):
            return -0.3
        return -0.65 if start or before.endswith(('"', '&&')) else -0.15
    if word == 'grep' and token.startswith(' '):
        return -1.2
    if word == 'python' and token.startswith(' '):
        return -0.8
    if word == '/python':
        return -0.85

    if token == '}{' and re.search(r'\\begin\{(?:array|tabular)$', text):
        return -4.7
    if word == '(' and text.rstrip().endswith('func'):
        return -3.3
    if word == 'package' and before.endswith('@'):
        return -11.0
    if word == 'crate' and text.rstrip().endswith('extern'):
        return -1.5
    if word == 'void':
        if re.search(r'\bprivate(?:\s+static)?\s*$', text):
            return -2.7
        if text.rstrip().endswith('protected'):
            return -2.0
        if re.search(r'\bpublic\s+static\s*$', text):
            return -0.25
        return -0.9 if text.rstrip().endswith('static') else -0.3
    if word in {'class', 'function'} and MODIFIER.search(text):
        return -2.9
    if word == 'namespace':
        if start:
            return -5.0 if 'using ' in text else -1.4
        if text.rstrip().endswith('using'):
            return -1.3
    if word == 'using' and start:
        return -3.8 if 'using ' in text else -1.3
    if start and word in {'def', 'func', 'package', 'import', 'class', 'function'}:
        if not before and word in {'package', 'class'}:
            return 0.55 if word == 'package' else 1.1
        # Line-numbered listings damp Python/Go declaration markers.
        listing = re.fullmatch(r'\s*\d+\s*', line)
        if listing and word in {'def', 'func', 'class'}:
            return -0.3 if word != 'class' else -0.7
        return {'def': -0.5, 'func': -0.6, 'package': -3.9,
                'import': -0.15, 'class': -1.2, 'function': -1.3}[word]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-1024:]), response(token, before)

programs.haiku:
"""Layer 1 MLP down-projection component 2558: a negative detector for the opening
token of a structured line.

It is near zero on ordinary prose and most code. It goes strongly negative on a few
kinds of line-opening token, and is weakly positive on a few others:

- diff headers: "+++" at a line start (about -11), the "a"/"b" path after "+++" or
  "---" (-4), "---" (-1.2);
- shell command openers: "cd" right after a JSON quote or "&&" (-3.6), other "cd" and
  tool names such as grep or cat (-0.7 to -0.9);
- code declarations: using / namespace / package / class / function / void after ";" or an
  access modifier (-2), at the start of a line (-1.1); Go "func (" (-3.5);
- field labels: a colon after a word that opens a line, as in "Posts:" or "title:" (-0.5),
  and after a few profile and front-matter fields wherever they occur (-3);
- positives: the name after "@param" (+4.9) and " PASS" in Go test output (+1.2).

Predictions are the mean activation of each case, so the program explains the large
negative spikes and leaves the rest near zero.
"""
from collections.abc import Mapping

READS = ()

MODIFIERS = {";", "public", "private", "protected", "static", "final", "export", "*/", "@@"}
DECLARATIONS = {"using", "namespace", "package", "class", "function", "void"}
SHELL_TOOLS = {"grep", "cat", "python", "/python"}
PROFILE_FIELDS = {"Joined", "Posts", "Category", "title", "Location", "deleted", "Subject", "Topic"}
PARAM_WORDS = {"param", "item", "paramref"}


def _back(prefix, k):
    """The token k places back, or None if it lies in an earlier document."""
    i = len(prefix.token_strings) - 1 - k
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return None
    return prefix.token_strings[i]


def _prev_word(prefix):
    """The nearest non-blank token before this one, stripped ('' if none)."""
    for k in range(1, 6):
        s = _back(prefix, k)
        if s is None:
            return ""
        if s.strip() or "\n" in s:
            return s.strip()
    return ""


def _line_start(prefix, first):
    """True if the nearest non-blank token from `first` places back ends a line."""
    for k in range(first, 6):
        s = _back(prefix, k)
        if s is None or (not s.strip() and "\n" not in s):
            continue
        return "\n" in s
    return False


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    prev = _prev_word(prefix)
    raw_prev = _back(prefix, 1) or ""
    value = 0.0
    if tok == "+++" and _line_start(prefix, 1):
        value = -11.0
    elif raw_prev in ("+++", "---") and tok in (" a", " b"):
        value = -4.0
    elif tok in ("---", " ---"):
        value = -1.2
    elif word == "cd":
        value = -3.6 if prev in ('"', "&&") else -0.9
    elif word in DECLARATIONS and prev in MODIFIERS:
        value = -2.0
    elif word == "(" and raw_prev.strip() == "func":
        value = -3.5
    elif word in DECLARATIONS and _line_start(prefix, 1):
        value = -1.1
    elif word in SHELL_TOOLS:
        value = -0.7
    elif word == ":" and prev in PROFILE_FIELDS:
        value = -3.0
    elif word == ":" and prev.isalpha() and _line_start(prefix, 2):
        value = -0.5
    elif tok == " name" and prev in PARAM_WORDS:
        value = 4.9
    elif tok == " PASS":
        value = 1.2
    return carry, value

programs.sol:
"""Approximate an exposed-eñe response rather than all Spanish words.

Short fragments ending in ñ are strongly negative; ñ-vowel syllables and
compañ-, señal and señor are weaker. Full words such as año, España and niño
are not given that response. It spills onto the next piece of the same
word. Spanish ya ('already/now') is positive, identified using nearby
function words. Capital Ñ outside Romance prose is treated more mildly:
it can instead be a mathematical N-tilde or an encoding error.
"""
import re

READS = ()
SPANISH = re.compile(
    r'\b(?:el|los|las|del|una|por|para|con|su|es|pero|lo|y)\b', re.I
)
ROMANCE = re.compile(r'\b(?:de|la|el|los|las|del|una|por|para)\b', re.I)


def letter_response(token, recent):
    s = token.strip()
    if s == 'Ñ':
        return -9.0 if ROMANCE.search(recent) else -1.0
    s = s.lower()
    if s.endswith('ñ') and len(s) <= 3:
        return -6.4
    if s in ('ña', 'ñas', 'ñe'):
        return -4.2
    if s == 'ño':
        return -3.2
    if s == 'ños':
        return -2.3
    if s == 'compañ':
        return -3.6
    if s in ('señal', 'señor'):
        return -3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, recent, previous = carry
    token = prefix.token_strings[-1]
    base = letter_response(token, recent)
    continuation = token[:1].isalpha()
    value = base + (0.35 * previous if continuation else 0.0)
    if token.strip().lower() == 'ya':
        if token[:1].isspace() or not recent[-1:].isalpha():
            value += 2.4 * min(1.0, len(SPANISH.findall(recent)) / 2)
    recent = (recent + token)[-200:]
    return (doc, recent, base), value
